values
  ('e21b2a1e-363c-4e86-b5d7-2b096cd0b1f8', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', null, 'topic'::public.curated_course_node_type, 'Foundations of Nursing Research and Evidence-Based Practice', 'This section establishes why disciplined inquiry is a professional nursing responsibility and how research, evidence-based practice, quality improvement, and implementation science work together without being interchangeable.', 0),
  ('c2d4f684-8b9c-4cfd-a880-eb0c2d68ef50', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', 'e21b2a1e-363c-4e86-b5d7-2b096cd0b1f8', 'subtopic'::public.curated_course_node_type, 'The research process', 'The research process turns uncertainty into a systematic, transparent investigation that can generate trustworthy and transferable knowledge.', 0),
