  ('a6e4d580-3f63-4cd6-aa06-ffe7f27ff4a5', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', 'e21b2a1e-363c-4e86-b5d7-2b096cd0b1f8', 'subtopic'::public.curated_course_node_type, 'Evidence-based practice as clinical reasoning', 'EBP is a decision process—not simply following a paper—that integrates best available evidence with expertise, patient goals, and the realities of a care setting.', 1),
