  ('b3508f7a-0edc-472b-8d87-8cd000bfa7ec', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', 'e21b2a1e-363c-4e86-b5d7-2b096cd0b1f8', 'subtopic'::public.curated_course_node_type, 'Research, EBP, QI, and implementation science', 'Knowing the distinctions prevents inappropriate claims, clarifies oversight, and helps teams choose methods that match their actual purpose.', 2),
