  ('fc48a1fc-ca7e-40bf-a831-fda459eed437', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', 'b3508f7a-0edc-472b-8d87-8cd000bfa7ec', 'concept'::public.curated_course_node_type, 'Program evaluation and operational analytics', null, 3),
  ('9caa01fc-5abf-491a-bb9d-2fb8661da0e9', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', 'b3508f7a-0edc-472b-8d87-8cd000bfa7ec', 'concept'::public.curated_course_node_type, 'When activities overlap and when consultation or review is needed', null, 4),
  ('6d89f863-7290-43c7-b5ed-07005abeb064', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', null, 'topic'::public.curated_course_node_type, 'Clinical Questions, Evidence Searching, and Information Stewardship', 'Strong evidence work begins with an answerable question and a search that another person could understand, reproduce, and update. This section builds efficient inquiry habits and guards against convenience-based evidence selection.', 1),
  ('d4693e7a-11a7-4bce-a22c-0940af28113a', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', '6d89f863-7290-43c7-b5ed-07005abeb064', 'subtopic'::public.curated_course_node_type, 'Question formulation', 'A structured question makes the population, uncertainty, outcomes, and decision visible so the search and appraisal remain clinically focused.', 0),
  ('2117bef8-9cea-4d59-9fba-26e66fcdbc91', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', 'd4693e7a-11a7-4bce-a22c-0940af28113a', 'concept'::public.curated_course_node_type, 'PICOT for interventions and therapy', null, 0),
  ('94814ec1-92e0-4c18-ac4c-80077516f702', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', 'd4693e7a-11a7-4bce-a22c-0940af28113a', 'concept'::public.curated_course_node_type, 'PEO/SPIDER for experiences and qualitative inquiry', null, 1),
