  ('5c916326-c1e3-4a0e-8148-488a33cfcb61', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', '6d89f863-7290-43c7-b5ed-07005abeb064', 'subtopic'::public.curated_course_node_type, 'Database searching', 'Searching is an iterative reasoning task that combines controlled vocabulary, keywords, logic, and database-specific translation.', 1),
