  ('fb8bb8ad-a74b-4baa-93ec-ecf404055425', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', '5c916326-c1e3-4a0e-8148-488a33cfcb61', 'concept'::public.curated_course_node_type, 'Search documentation and peer review', null, 4),
  ('62b47397-6091-410a-bea4-60d221e1843b', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', '6d89f863-7290-43c7-b5ed-07005abeb064', 'subtopic'::public.curated_course_node_type, 'Evidence and citation management', 'Organized records reduce duplication, support transparent screening, and preserve a defensible path from question to included evidence.', 2),
