  ('4824d207-d98b-4f68-8684-8433b4fe6f3b', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', '62b47397-6091-410a-bea4-60d221e1843b', 'concept'::public.curated_course_node_type, 'Evidence tables and annotated bibliographies', null, 2),
  ('68ba5646-2c00-4ea8-a2bf-a74d4dcf186e', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', '62b47397-6091-410a-bea4-60d221e1843b', 'concept'::public.curated_course_node_type, 'Persistent identifiers, versions, and retractions', null, 3),
  ('2965850d-5c4c-4d22-b987-c7c6014ba206', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', '62b47397-6091-410a-bea4-60d221e1843b', 'concept'::public.curated_course_node_type, 'Copyright, licensing, data privacy, and information security', null, 4),
  ('e2b72e79-fa6f-48f8-b73b-8e13fdf04b0c', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', null, 'topic'::public.curated_course_node_type, 'Quantitative Research Designs, Sampling, and Measurement', 'Quantitative research estimates relationships, differences, diagnostic accuracy, and intervention effects. Learners focus on how design choices shape causal claims, bias, precision, and applicability.', 2),
  ('0242ba97-3b5e-46a7-ae0b-0329fa00f03f', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', 'e2b72e79-fa6f-48f8-b73b-8e13fdf04b0c', 'subtopic'::public.curated_course_node_type, 'Experimental and quasi-experimental designs', 'Intervention designs test whether changing an exposure or practice produces a meaningful outcome, with varying protection against confounding.', 0);
