  ('29da5ad2-fdbf-4fd9-8c6b-1ecc03c3edec', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', '51df8daf-dafd-4517-a760-bd643837bdb5', 'concept'::public.curated_course_node_type, 'Confounding, selection bias, information bias, and reverse causation', null, 2),
