  ('4fdd0b99-8c3a-40e8-b899-09f733879314', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', '51df8daf-dafd-4517-a760-bd643837bdb5', 'concept'::public.curated_course_node_type, 'Applicability to nursing populations and settings', null, 4),
  ('c28b7ed4-55c3-4205-9483-4f331dba64ab', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', 'e2b72e79-fa6f-48f8-b73b-8e13fdf04b0c', 'subtopic'::public.curated_course_node_type, 'Sampling and measurement', 'A result is only as useful as the people represented and the measures used to describe them.', 2),
