  ('3e34ca5d-1b20-47a4-b6d9-cc51a4629b0d', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', 'c28b7ed4-55c3-4205-9483-4f331dba64ab', 'concept'::public.curated_course_node_type, 'Reliability, validity, responsiveness, and measurement error', null, 3),
  ('8c3a7c65-3daa-4636-9833-356dcb2e2a17', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', 'c28b7ed4-55c3-4205-9483-4f331dba64ab', 'concept'::public.curated_course_node_type, 'Patient-reported outcomes, clinical measures, and meaningful thresholds', null, 4),
  ('2dc773be-98ef-439d-a1d8-85a98a76e631', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', null, 'topic'::public.curated_course_node_type, 'Statistical Reasoning and Data Interpretation', 'Nurses need statistical literacy to judge claims and explain uncertainty—not to worship a threshold. This section emphasizes interpretation, clinical importance, and transparent communication.', 3),
  ('ec20b250-474e-42ad-8b72-ee36a4ebb1ce', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', '2dc773be-98ef-439d-a1d8-85a98a76e631', 'subtopic'::public.curated_course_node_type, 'Describing data', 'Descriptive statistics reveal the shape, center, spread, and quality of clinical data before inferential conclusions are attempted.', 0),
