  ('63282cd1-b085-4281-afa6-e86ca170cebd', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', 'ec20b250-474e-42ad-8b72-ee36a4ebb1ce', 'concept'::public.curated_course_node_type, 'Missing data, outliers, data quality, and denominator integrity', null, 4),
  ('3762b786-02e1-4ac3-9aa6-9f5f9cbccce7', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', '2dc773be-98ef-439d-a1d8-85a98a76e631', 'subtopic'::public.curated_course_node_type, 'Estimating effects and uncertainty', 'Effect estimates and confidence intervals show magnitude and precision, helping readers move beyond the binary language of statistical significance.', 1),
