  ('dbcb7256-1133-4ab0-b6a2-fdfd8bb5dc5d', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', '3762b786-02e1-4ac3-9aa6-9f5f9cbccce7', 'concept'::public.curated_course_node_type, 'Confidence intervals and standard errors', null, 2),
  ('da6c7d96-46c9-4638-a6bd-9f79c90a56ce', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', '3762b786-02e1-4ac3-9aa6-9f5f9cbccce7', 'concept'::public.curated_course_node_type, 'P values, Type I/II errors, multiplicity, and power', null, 3),
