  ('6c2d58e5-1beb-4cd2-b80d-7862a771a9e8', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', '2dc773be-98ef-439d-a1d8-85a98a76e631', 'subtopic'::public.curated_course_node_type, 'Common analyses and responsible interpretation', 'Understanding what an analysis compares and assumes helps learners detect exaggerated, unsupported, or misleading claims.', 2),
