  ('7f77773c-7a51-4149-b6ef-a7d0ab552948', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', null, 'topic'::public.curated_course_node_type, 'Qualitative and Mixed-Methods Inquiry', 'Qualitative evidence makes experience, meaning, culture, workflow, and context visible. Mixed methods intentionally connects numerical patterns with explanatory depth to answer complex practice questions.', 4),
