  ('ecfafb4c-4b37-4c93-ac5e-6e2f5fa9337d', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', null, 'topic'::public.curated_course_node_type, 'Critical Appraisal of Individual Studies', 'Critical appraisal asks whether a study is trustworthy, what it actually shows, and whether it helps with a specific decision. The goal is calibrated judgment rather than checklist completion.', 5),
  ('ccfc1dea-1157-4c33-8e37-fdba53a45ea3', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', 'ecfafb4c-4b37-4c93-ac5e-6e2f5fa9337d', 'subtopic'::public.curated_course_node_type, 'Validity and risk of bias', 'Internal validity concerns whether the observed result is a credible estimate for the study participants.', 0),
