  ('d1b1d1b6-8e16-4ba1-9f9f-056482334a38', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', 'ccfc1dea-1157-4c33-8e37-fdba53a45ea3', 'concept'::public.curated_course_node_type, 'Confounding and baseline imbalance', null, 1),
