  ('81696df3-1b90-4800-b29f-ff687ee4a2f2', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', null, 'topic'::public.curated_course_node_type, 'Evidence Synthesis, Meta-analysis, and Certainty', 'No single study settles most practice questions. This section shows how systematic reviews assemble evidence, how meta-analysis combines estimates, and how certainty should constrain recommendations.', 6),
