  ('6e760475-eeac-4f9d-81c5-89b653ffd0bd', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', '63ea74c4-5717-4149-9572-2d7cbb93bb07', 'subtopic'::public.curated_course_node_type, 'From recommendation to decision', 'Recommendations guide but do not erase clinical judgment; decision-making must account for benefits, harms, burdens, resources, and what matters to the person.', 1),
