  ('1fc880c7-ef60-4162-ba69-65f5b98c5e46', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', null, 'topic'::public.curated_course_node_type, 'Translation, Evaluation, Informatics, and Responsible AI', 'Translation connects implementation activities to measurable outcomes and learning. Digital systems can accelerate evidence use, but they also introduce workflow, privacy, bias, and automation risks.', 10),
  ('be47e36d-2129-4efc-9ab1-3f7144e71c76', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', '1fc880c7-ef60-4162-ba69-65f5b98c5e46', 'subtopic'::public.curated_course_node_type, 'Implementation and outcome evaluation', 'A useful evaluation distinguishes whether a practice was implemented from whether it improved care and checks for unintended effects.', 0),
  ('102ac180-8832-4459-857e-177e4ea0748d', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', 'be47e36d-2129-4efc-9ab1-3f7144e71c76', 'concept'::public.curated_course_node_type, 'Structure, process, outcome, and balancing measures', null, 0),
  ('a00886d3-4826-47b5-ba9d-93415e414032', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', 'be47e36d-2129-4efc-9ab1-3f7144e71c76', 'concept'::public.curated_course_node_type, 'Implementation outcomes: acceptability, adoption, appropriateness, feasibility, fidelity, cost, penetration, sustainment', null, 1),
  ('21d8ad34-dd64-4808-ad42-ec070f4d9db8', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', 'be47e36d-2129-4efc-9ab1-3f7144e71c76', 'concept'::public.curated_course_node_type, 'Operational definitions, data sources, collection frequency, and data quality', null, 2),
  ('0b4d8aab-5237-4898-b814-0fd0376e5524', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', 'be47e36d-2129-4efc-9ab1-3f7144e71c76', 'concept'::public.curated_course_node_type, 'Baseline, targets, benchmarks, and stratification', null, 3),
  ('71a91811-7a6f-4bd5-8685-6bb84bd9c301', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', 'be47e36d-2129-4efc-9ab1-3f7144e71c76', 'concept'::public.curated_course_node_type, 'Logic models and contribution versus causal attribution', null, 4),
  ('eb742085-5400-40db-9157-f958d59ca230', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', '1fc880c7-ef60-4162-ba69-65f5b98c5e46', 'subtopic'::public.curated_course_node_type, 'QI analytics and learning over time', 'Time-ordered data helps teams distinguish common variation from meaningful change and supports rapid learning during implementation.', 1),
  ('23b40c2f-dfd0-4424-b65d-618892879b53', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', 'eb742085-5400-40db-9157-f958d59ca230', 'concept'::public.curated_course_node_type, 'Plan–Do–Study–Act cycles', null, 0),
