  ('6b6a6210-f576-4f68-8760-3b6929bdac32', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', null, 'topic'::public.curated_course_node_type, 'Dissemination, Sustainability, and Knowledge Mobilization', 'The final section turns sound analysis into action. Learners tailor messages to audiences, plan for sustainment and spread, and make evidence products transparent enough to support future updating.', 11),
  ('e7b42d8f-847f-4c5c-b23b-fa7ec5e9e3a2', 'a7c3e1d4-8b26-4f05-9c18-5d2e0a9b6f31', '6b6a6210-f576-4f68-8760-3b6929bdac32', 'subtopic'::public.curated_course_node_type, 'Scholarly and professional dissemination', 'Different audiences need different levels of detail, but every format should preserve the evidence''s strength, uncertainty, limitations, and implications.', 0),
