select
  'nursing-research-and-evidence-based-practice',
  null,
  'Nursing Research and Evidence-Based Practice',
  'Nursing Research and Evidence-Based Practice',
  'This integrated course develops the knowledge, judgment, and practical skills nurses need to ask answerable clinical questions, find and critically appraise research, integrate evidence with clinical expertise and patient values, and lead ethical, equitable improvements in care. BSN learners build confident research literacy and contribute to evidence-based change; MSN learners additionally evaluate complex bodies of evidence, select implementation strategies, measure outcomes, and lead dissemination.',
  $nrebpjson${"slug": "nursing-research-and-evidence-based-practice", "title": "Nursing Research and Evidence-Based Practice", "description": "This integrated course develops the knowledge, judgment, and practical skills nurses need to ask answerable clinical questions, find and critically appraise research, integrate evidence with clinical expertise and patient values, and lead ethical, equitable improvements in care. BSN learners build confident research literacy and contribute to evidence-based change; MSN learners additionally evaluate complex bodies of evidence, select implementation strategies, measure outcomes, and lead dissemination.", "topics": [{"id": "e21b2a1e-363c-4e86-b5d7-2b096cd0b1f8", "type": "topic", "title": "Foundations of Nursing Research and Evidence-Based Practice", "description": "This section establishes why disciplined inquiry is a professional nursing responsibility and how research, evidence-based practice, quality improvement, and implementation science work together without being interchangeable.", "children": [{"id": "c2d4f684-8b9c-4cfd-a880-eb0c2d68ef50", "type": "subtopic", "title": "The research process", "children": [{"id": "281fa719-86a2-4184-a955-5a930cc3952b", "type": "concept", "title": "Problem identification and significance"}, {"id": "9079b69e-fad9-446f-b474-f7745266a6c9", "type": "concept", "title": "Purpose statements, aims, questions, and hypotheses"}, {"id": "5b9a7326-de6d-4361-89bc-a5747c86615e", "type": "concept", "title": "Conceptual and theoretical frameworks"}, {"id": "51719220-b525-4558-b8b3-2e0b949888b4", "type": "concept", "title": "Literature review, design, data collection, analysis, interpretation, and reporting"}, {"id": "c157e2d4-c634-4faf-9233-04b6a7baed57", "type": "concept", "title": "Replication, reproducibility, transparency, and open-science principles"}], "description": "The research process turns uncertainty into a systematic, transparent investigation that can generate trustworthy and transferable knowledge."}, {"id": "a6e4d580-3f63-4cd6-aa06-ffe7f27ff4a5", "type": "subtopic", "title": "Evidence-based practice as clinical reasoning", "children": [{"id": "8a9b241c-a6e4-4307-89f7-2d5db104c75c", "type": "concept", "title": "Best research evidence"}, {"id": "0bfaebf7-bb39-4912-b0b2-be56637f2330", "type": "concept", "title": "Clinical expertise and professional judgment"}, {"id": "5dc964cd-0f59-4433-84ec-0316472d7816", "type": "concept", "title": "Patient values, goals, culture, and preferences"}, {"id": "c288cc40-5f97-414f-88a6-ff03f76a1e41", "type": "concept", "title": "Local data, resources, feasibility, and context"}, {"id": "383057d7-4710-4618-95e6-3635b5d89640", "type": "concept", "title": "Shared decision-making and person-centered care"}], "description": "EBP is a decision process—not simply following a paper—that integrates best available evidence with expertise, patient goals, and the realities of a care setting."}, {"id": "b3508f7a-0edc-472b-8d87-8cd000bfa7ec", "type": "subtopic", "title": "Research, EBP, QI, and implementation science", "children": [{"id": "74a0bc05-6570-4158-8fe5-204a74b1d081", "type": "concept", "title": "Knowledge generation versus local improvement"}, {"id": "a51e0fec-26d4-4b3d-be7c-cbbb47f74ff6", "type": "concept", "title": "QI cycles and process control"}, {"id": "88be5a53-6d22-4c14-8598-68fadd4ee024", "type": "concept", "title": "Evidence translation and implementation research"}, {"id": "fc48a1fc-ca7e-40bf-a831-fda459eed437", "type": "concept", "title": "Program evaluation and operational analytics"}, {"id": "9caa01fc-5abf-491a-bb9d-2fb8661da0e9", "type": "concept", "title": "When activities overlap and when consultation or review is needed"}], "description": "Knowing the distinctions prevents inappropriate claims, clarifies oversight, and helps teams choose methods that match their actual purpose."}]}, {"id": "6d89f863-7290-43c7-b5ed-07005abeb064", "type": "topic", "title": "Clinical Questions, Evidence Searching, and Information Stewardship", "description": "Strong evidence work begins with an answerable question and a search that another person could understand, reproduce, and update. This section builds efficient inquiry habits and guards against convenience-based evidence selection.", "children": [{"id": "d4693e7a-11a7-4bce-a22c-0940af28113a", "type": "subtopic", "title": "Question formulation", "children": [{"id": "2117bef8-9cea-4d59-9fba-26e66fcdbc91", "type": "concept", "title": "PICOT for interventions and therapy"}, {"id": "94814ec1-92e0-4c18-ac4c-80077516f702", "type": "concept", "title": "PEO/SPIDER for experiences and qualitative inquiry"}, {"id": "200fdb28-fb44-4f95-9070-35e61d4e581d", "type": "concept", "title": "Etiology, harm, diagnosis, prognosis, and prevalence questions"}, {"id": "cd4298b4-6427-4081-b3db-8ed6b2967d85", "type": "concept", "title": "Foreground versus background questions"}, {"id": "cadd8c46-0649-4fd9-966c-ec847afc09b4", "type": "concept", "title": "Outcome prioritization with patients and stakeholders"}], "description": "A structured question makes the population, uncertainty, outcomes, and decision visible so the search and appraisal remain clinically focused."}, {"id": "5c916326-c1e3-4a0e-8148-488a33cfcb61", "type": "subtopic", "title": "Database searching", "children": [{"id": "56106d63-6d16-404d-8100-6abea98cd7aa", "type": "concept", "title": "PubMed/MEDLINE and CINAHL roles"}, {"id": "9636009b-620e-4376-9c9e-581a343b1dca", "type": "concept", "title": "Subject headings and text words"}, {"id": "154dd5c7-45ab-47dd-bb9c-c73bc8554192", "type": "concept", "title": "Boolean logic, phrase searching, truncation, and proximity"}, {"id": "8a471e78-c254-495b-abfd-d55866875790", "type": "concept", "title": "Filters, limits, citation chaining, and grey literature"}, {"id": "fb8bb8ad-a74b-4baa-93ec-ecf404055425", "type": "concept", "title": "Search documentation and peer review"}], "description": "Searching is an iterative reasoning task that combines controlled vocabulary, keywords, logic, and database-specific translation."}, {"id": "62b47397-6091-410a-bea4-60d221e1843b", "type": "subtopic", "title": "Evidence and citation management", "children": [{"id": "c8762c85-3c24-4006-90ad-77dcfd23a8b6", "type": "concept", "title": "Citation managers and deduplication"}, {"id": "f79a36e5-90a8-4c6e-9985-b8b4ff6e3947", "type": "concept", "title": "Eligibility criteria and screening logs"}, {"id": "4824d207-d98b-4f68-8684-8433b4fe6f3b", "type": "concept", "title": "Evidence tables and annotated bibliographies"}, {"id": "68ba5646-2c00-4ea8-a2bf-a74d4dcf186e", "type": "concept", "title": "Persistent identifiers, versions, and retractions"}, {"id": "2965850d-5c4c-4d22-b987-c7c6014ba206", "type": "concept", "title": "Copyright, licensing, data privacy, and information security"}], "description": "Organized records reduce duplication, support transparent screening, and preserve a defensible path from question to included evidence."}]}, {"id": "e2b72e79-fa6f-48f8-b73b-8e13fdf04b0c", "type": "topic", "title": "Quantitative Research Designs, Sampling, and Measurement", "description": "Quantitative research estimates relationships, differences, diagnostic accuracy, and intervention effects. Learners focus on how design choices shape causal claims, bias, precision, and applicability.", "children": [{"id": "0242ba97-3b5e-46a7-ae0b-0329fa00f03f", "type": "subtopic", "title": "Experimental and quasi-experimental designs", "children": [{"id": "86326a5c-4945-4b81-98d3-3efd29ccbbb4", "type": "concept", "title": "Randomized controlled trials and allocation concealment"}, {"id": "ac558a46-1ae1-41a9-96d9-e94ff49ee7d2", "type": "concept", "title": "Blinding, comparators, contamination, and co-interventions"}, {"id": "f5065867-42a3-4b66-a342-db9351b0c902", "type": "concept", "title": "Pragmatic, cluster, crossover, and stepped-wedge trials"}, {"id": "06037318-50c0-4495-afe0-d34dacfc7699", "type": "concept", "title": "Quasi-experimental, interrupted time-series, and pre/post designs"}, {"id": "9b7fd88e-f307-4aa0-9740-11d888f3792c", "type": "concept", "title": "Protocol deviations, attrition, and intention-to-treat reasoning"}], "description": "Intervention designs test whether changing an exposure or practice produces a meaningful outcome, with varying protection against confounding."}, {"id": "51df8daf-dafd-4517-a760-bd643837bdb5", "type": "subtopic", "title": "Observational designs", "children": [{"id": "7787a96c-5d20-45f0-a061-c088d78227d1", "type": "concept", "title": "Cohort, case-control, cross-sectional, and ecological designs"}, {"id": "7bc8b85c-58e2-4082-81ee-2aa241e08764", "type": "concept", "title": "Prospective versus retrospective data"}, {"id": "29da5ad2-fdbf-4fd9-8c6b-1ecc03c3edec", "type": "concept", "title": "Confounding, selection bias, information bias, and reverse causation"}, {"id": "a1bdcc2c-bf35-4bf1-b70a-326958ee7f85", "type": "concept", "title": "Risk adjustment and causal diagrams as conceptual tools"}, {"id": "4fdd0b99-8c3a-40e8-b899-09f733879314", "type": "concept", "title": "Applicability to nursing populations and settings"}], "description": "Observational studies are essential for prevalence, prognosis, risk, harm, and real-world questions, but their conclusions depend heavily on bias control."}, {"id": "c28b7ed4-55c3-4205-9483-4f331dba64ab", "type": "subtopic", "title": "Sampling and measurement", "children": [{"id": "1ab42805-ba2e-44ae-97ad-d3ec916053e9", "type": "concept", "title": "Probability and nonprobability sampling"}, {"id": "136f97ea-fe1e-4871-8c8e-ef08e4ae6708", "type": "concept", "title": "Recruitment, inclusion, exclusion, and retention"}, {"id": "301c9ada-8f6e-46f2-87ca-38f5f3a05272", "type": "concept", "title": "Power, sample size, precision, and feasibility"}, {"id": "3e34ca5d-1b20-47a4-b6d9-cc51a4629b0d", "type": "concept", "title": "Reliability, validity, responsiveness, and measurement error"}, {"id": "8c3a7c65-3daa-4636-9833-356dcb2e2a17", "type": "concept", "title": "Patient-reported outcomes, clinical measures, and meaningful thresholds"}], "description": "A result is only as useful as the people represented and the measures used to describe them."}]}, {"id": "2dc773be-98ef-439d-a1d8-85a98a76e631", "type": "topic", "title": "Statistical Reasoning and Data Interpretation", "description": "Nurses need statistical literacy to judge claims and explain uncertainty—not to worship a threshold. This section emphasizes interpretation, clinical importance, and transparent communication.", "children": [{"id": "ec20b250-474e-42ad-8b72-ee36a4ebb1ce", "type": "subtopic", "title": "Describing data", "children": [{"id": "05b348ee-24eb-43aa-94d7-292b0198fb09", "type": "concept", "title": "Variable types and distributions"}, {"id": "51a6b36a-8a6c-4439-8007-cb866543ae99", "type": "concept", "title": "Mean, median, mode, range, variance, and standard deviation"}, {"id": "f7586266-9814-4114-b8f6-c9ea5e018fa9", "type": "concept", "title": "Rates, ratios, proportions, incidence, and prevalence"}, {"id": "c42b0b30-a751-4cf7-83da-b5cffbd5f2a4", "type": "concept", "title": "Tables, histograms, box plots, and data visualization"}, {"id": "63282cd1-b085-4281-afa6-e86ca170cebd", "type": "concept", "title": "Missing data, outliers, data quality, and denominator integrity"}], "description": "Descriptive statistics reveal the shape, center, spread, and quality of clinical data before inferential conclusions are attempted."}, {"id": "3762b786-02e1-4ac3-9aa6-9f5f9cbccce7", "type": "subtopic", "title": "Estimating effects and uncertainty", "children": [{"id": "3024d279-dc86-4729-9915-c8d0ce823a2a", "type": "concept", "title": "Risk ratio, odds ratio, hazard ratio, and mean difference"}, {"id": "4d73a203-20fa-4588-ac3a-8e7fd7b89d0d", "type": "concept", "title": "Absolute risk difference and number needed to treat/harm"}, {"id": "dbcb7256-1133-4ab0-b6a2-fdfd8bb5dc5d", "type": "concept", "title": "Confidence intervals and standard errors"}, {"id": "da6c7d96-46c9-4638-a6bd-9f79c90a56ce", "type": "concept", "title": "P values, Type I/II errors, multiplicity, and power"}, {"id": "ca04c01c-eba0-487f-ac3e-091fb68427bb", "type": "concept", "title": "Statistical versus clinical significance"}], "description": "Effect estimates and confidence intervals show magnitude and precision, helping readers move beyond the binary language of statistical significance."}, {"id": "6c2d58e5-1beb-4cd2-b80d-7862a771a9e8", "type": "subtopic", "title": "Common analyses and responsible interpretation", "children": [{"id": "e2760e45-b686-4df4-9b4f-a74c29dbae9d", "type": "concept", "title": "t tests, ANOVA, chi-square, correlation, and regression"}, {"id": "611814fa-ff83-40d5-9fa6-f029de05cf92", "type": "concept", "title": "Adjusted versus unadjusted estimates"}, {"id": "89b1adf5-b135-49d8-b7e7-6f715682bf64", "type": "concept", "title": "Interaction, subgroup analysis, and confounding"}, {"id": "91975ee9-571a-4845-820f-409bb36f1bb1", "type": "concept", "title": "Survival analysis and time-to-event basics"}, {"id": "b9a9a504-e810-4231-a944-c4f7e3fbe96a", "type": "concept", "title": "Graduate extension: model fit, assumptions, sensitivity analysis, and reproducible code"}], "description": "Understanding what an analysis compares and assumes helps learners detect exaggerated, unsupported, or misleading claims."}]}, {"id": "7f77773c-7a51-4149-b6ef-a7d0ab552948", "type": "topic", "title": "Qualitative and Mixed-Methods Inquiry", "description": "Qualitative evidence makes experience, meaning, culture, workflow, and context visible. Mixed methods intentionally connects numerical patterns with explanatory depth to answer complex practice questions.", "children": [{"id": "647b1ae5-6846-4347-93b7-5e7dc3578b93", "type": "subtopic", "title": "Qualitative traditions and questions", "children": [{"id": "be11ab62-c702-49e3-b1fc-42dd1478b40b", "type": "concept", "title": "Phenomenology, grounded theory, ethnography, case study, and qualitative description"}, {"id": "fb9a3bf3-9e05-475f-9dc3-04a9043eb695", "type": "concept", "title": "Researcher positionality and reflexivity"}, {"id": "1af423e4-cf7e-4fea-b302-6cbe574a2ae9", "type": "concept", "title": "Purposive, theoretical, and snowball sampling"}, {"id": "2f1350e9-a447-4692-98ee-b043ebbbe746", "type": "concept", "title": "Saturation and information power"}, {"id": "e7c278a0-4a46-4937-99b6-66322961d4b9", "type": "concept", "title": "Interviews, focus groups, observation, documents, and digital data"}], "description": "Methodological traditions shape what counts as data, how participants are engaged, and what kind of knowledge a study can claim."}, {"id": "6ed7eac7-c4d3-4002-b1d1-baa645c79174", "type": "subtopic", "title": "Qualitative analysis and rigor", "children": [{"id": "8d352b96-8fee-4475-a50b-86909e57454b", "type": "concept", "title": "Coding, categorization, memoing, and theme development"}, {"id": "8c9d3e6b-c56e-48a8-afdb-47e651601986", "type": "concept", "title": "Inductive, deductive, and abductive reasoning"}, {"id": "1e39d659-6ba3-4169-9b5d-ab22170d8d09", "type": "concept", "title": "Credibility, dependability, confirmability, and transferability"}, {"id": "f6a87797-1455-4d3f-83ad-9b806ecbe0cc", "type": "concept", "title": "Triangulation, member reflection, audit trails, and negative cases"}, {"id": "3376944f-0477-4637-844d-ad44e29a846e", "type": "concept", "title": "Representation, quotation, confidentiality, and interpretive humility"}], "description": "Systematic analysis makes the path from raw accounts to interpretations visible and credible."}, {"id": "c155693f-f8f3-4b41-9c63-22ced680ab27", "type": "subtopic", "title": "Mixed-methods integration", "children": [{"id": "e8c61be6-30ef-48db-a95e-a2e5397f46a0", "type": "concept", "title": "Convergent, explanatory sequential, and exploratory sequential designs"}, {"id": "c7500794-d172-4681-90d7-9e37206ffc8a", "type": "concept", "title": "Connecting, building, merging, and embedding"}, {"id": "88b71ff0-6d78-44fd-b33d-1a2de548abe2", "type": "concept", "title": "Joint displays and meta-inferences"}, {"id": "3d8ba588-5aed-4bcc-8930-635b89aae87b", "type": "concept", "title": "Managing discordant findings"}, {"id": "650c5138-cc20-4b3d-8722-7e35d363e996", "type": "concept", "title": "Graduate extension: integration quality and mixed-methods legitimation"}], "description": "Mixed methods adds value only when qualitative and quantitative strands are deliberately connected and produce insight beyond parallel results."}]}, {"id": "ecfafb4c-4b37-4c93-ac5e-6e2f5fa9337d", "type": "topic", "title": "Critical Appraisal of Individual Studies", "description": "Critical appraisal asks whether a study is trustworthy, what it actually shows, and whether it helps with a specific decision. The goal is calibrated judgment rather than checklist completion.", "children": [{"id": "ccfc1dea-1157-4c33-8e37-fdba53a45ea3", "type": "subtopic", "title": "Validity and risk of bias", "children": [{"id": "a0c1daa6-29d3-4ebe-8729-d5858b43afa3", "type": "concept", "title": "Selection, performance, detection, attrition, and reporting bias"}, {"id": "d1b1d1b6-8e16-4ba1-9f9f-056482334a38", "type": "concept", "title": "Confounding and baseline imbalance"}, {"id": "c66171a5-fc35-4387-a488-a4fbb08846c3", "type": "concept", "title": "Measurement validity and outcome ascertainment"}, {"id": "56fcdd15-6e06-4304-91c0-d6856d6d91dc", "type": "concept", "title": "Selective outcomes, spin, protocol registration, and conflicts of interest"}, {"id": "323ee603-f80f-4c68-bb1d-70e7dadfa990", "type": "concept", "title": "Design-specific appraisal tools and domain-based judgments"}], "description": "Internal validity concerns whether the observed result is a credible estimate for the study participants."}, {"id": "cb919a03-06a1-435a-a769-46e0f0522f2b", "type": "subtopic", "title": "Results and precision", "children": [{"id": "586e5332-027c-4dfa-94db-4c7d9d3277e3", "type": "concept", "title": "Effect size and direction"}, {"id": "81b3232b-7ea8-44ed-9a11-81cbd998c45b", "type": "concept", "title": "Confidence intervals and imprecision"}, {"id": "36f4fa3c-53d3-404d-89ce-b65ea9e9c150", "type": "concept", "title": "Clinical importance and minimal important differences"}, {"id": "ba42d98e-1ae4-4209-bb47-1d25126f318c", "type": "concept", "title": "Harms, burden, and unintended effects"}, {"id": "09fd3ab9-a925-4c18-b728-b737dc6f28ee", "type": "concept", "title": "Qualitative richness, coherence, and supporting data"}], "description": "Learners translate statistical and qualitative findings into plain-language statements that preserve magnitude, uncertainty, and limitations."}, {"id": "4835ea21-76e0-48db-90d5-55fe3d5d6282", "type": "subtopic", "title": "Applicability and equity", "children": [{"id": "1a705777-3f3f-4ba6-b058-98ec143c125a", "type": "concept", "title": "Population and setting similarity"}, {"id": "d43c264a-fbc7-43fa-9b9f-bbdb7d52af57", "type": "concept", "title": "Feasibility, acceptability, cost, and workflow"}, {"id": "2304cb5e-ff8c-4a5c-950a-910b60f06d2e", "type": "concept", "title": "Patient goals and treatment burden"}, {"id": "a7a303b8-a067-4be4-afc0-27b8fd0d84b5", "type": "concept", "title": "Representation and subgroup credibility"}, {"id": "7b75ca4d-4b73-4382-b55a-28c5454f0509", "type": "concept", "title": "PROGRESS-Plus and equity-relevant applicability checks"}], "description": "External validity asks whether evidence fits the patient, population, team, setting, and resources involved in the decision."}]}, {"id": "81696df3-1b90-4800-b29f-ff687ee4a2f2", "type": "topic", "title": "Evidence Synthesis, Meta-analysis, and Certainty", "description": "No single study settles most practice questions. This section shows how systematic reviews assemble evidence, how meta-analysis combines estimates, and how certainty should constrain recommendations.", "children": [{"id": "344e213e-fe66-4da7-9810-1ebc16741ff7", "type": "subtopic", "title": "Systematic review methods", "children": [{"id": "c71b7e9d-84cc-4898-a8b8-aec694c4ecf5", "type": "concept", "title": "Protocol registration and reporting standards"}, {"id": "71df94c1-0799-43da-ab96-04abfbe61904", "type": "concept", "title": "Comprehensive searching and study selection"}, {"id": "88815e6f-fb44-4530-a308-7109ab3241e9", "type": "concept", "title": "Data extraction and duplicate processes"}, {"id": "20a2bd5d-d6ae-400f-82df-5e6a4e23e75a", "type": "concept", "title": "Risk-of-bias assessment across designs"}, {"id": "b58b1c0e-1833-42a6-af38-0351a159f425", "type": "concept", "title": "Narrative synthesis and transparent exclusions"}], "description": "A trustworthy review uses prespecified, reproducible methods to reduce bias in finding, selecting, appraising, and synthesizing studies."}, {"id": "290d30e0-78c0-4e2e-b475-1d6c7e7335e8", "type": "subtopic", "title": "Meta-analysis interpretation", "children": [{"id": "730aeb2f-f489-4cb3-bfcf-623d7302b489", "type": "concept", "title": "Forest plots, weights, and pooled effects"}, {"id": "7c10b077-69f9-432f-b021-b5f3effd9e1a", "type": "concept", "title": "Fixed-effect and random-effects models"}, {"id": "ba6fb880-238c-4e3e-8c79-dd6ed1bac0ea", "type": "concept", "title": "Clinical, methodological, and statistical heterogeneity"}, {"id": "e399b458-f403-4454-939d-262d5d9fcf99", "type": "concept", "title": "I², prediction intervals, subgroup and sensitivity analyses"}, {"id": "e62041ae-5d8d-4c64-b75d-7dfee6611a70", "type": "concept", "title": "Publication bias, small-study effects, and funnel plots"}], "description": "Meta-analysis increases precision when studies are sufficiently compatible, but a pooled number cannot repair biased or incomparable evidence."}, {"id": "8abd60c7-41a7-41e2-a252-abd31e111dd5", "type": "subtopic", "title": "Levels of evidence and certainty grading", "children": [{"id": "befad3ec-3d01-4d87-bf6a-dc2d264fa274", "type": "concept", "title": "Study-design hierarchies and their limits"}, {"id": "78068785-cfba-4209-a556-275da50738cf", "type": "concept", "title": "GRADE domains: risk of bias, inconsistency, indirectness, imprecision, publication bias"}, {"id": "fbfbd6ee-348e-4874-8661-437d9298bd7c", "type": "concept", "title": "Upgrading considerations for observational evidence"}, {"id": "b9db85e2-5d75-4a10-8c81-eeb5970f1760", "type": "concept", "title": "High, moderate, low, and very-low certainty"}, {"id": "1a16cc87-44a6-4121-b6fb-f6964c21358b", "type": "concept", "title": "Strength of recommendation versus certainty of evidence"}], "description": "Evidence hierarchies are useful shortcuts, while certainty frameworks support a more nuanced judgment across an entire body of evidence."}]}, {"id": "63ea74c4-5717-4149-9572-2d7cbb93bb07", "type": "topic", "title": "Clinical Practice Guidelines and Evidence-Based Decisions", "description": "Guidelines translate bodies of evidence into recommendations, but quality, currency, conflicts, feasibility, and patient values still require scrutiny before adoption.", "children": [{"id": "37da6a86-8e70-48f7-a89a-aa431ce31d0b", "type": "subtopic", "title": "Guideline development and appraisal", "children": [{"id": "7ded6d2d-d09a-462b-9b30-3b1748ca11e4", "type": "concept", "title": "Scope, stakeholder representation, and patient involvement"}, {"id": "08ba8736-625f-411e-8d73-6e18b693c1bc", "type": "concept", "title": "Systematic evidence review and evidence-to-decision frameworks"}, {"id": "05074449-c55e-4a25-b0d6-1edf3d21d250", "type": "concept", "title": "AGREE II domains"}, {"id": "304081ff-7723-4bd4-9601-7a575ecbbc61", "type": "concept", "title": "Conflict-of-interest management and editorial independence"}, {"id": "0ae12ecf-bbee-47f5-ad60-8727a74f4a0b", "type": "concept", "title": "Currency, updating, and living guidelines"}], "description": "Credible guidelines connect transparent evidence review with multidisciplinary deliberation and explicit management of conflicts."}, {"id": "6e760475-eeac-4f9d-81c5-89b653ffd0bd", "type": "subtopic", "title": "From recommendation to decision", "children": [{"id": "c611463a-1c1c-4492-ba1b-b4b6dc4a7fa7", "type": "concept", "title": "Strong versus conditional recommendations"}, {"id": "1031be60-e8f0-4fd3-93bd-e49c4f99b843", "type": "concept", "title": "Shared decision-making and decision aids"}, {"id": "ad78009d-90da-426e-9637-fc45e486a2e9", "type": "concept", "title": "Absolute effects and baseline risk"}, {"id": "5f96afc6-d899-4bc1-8a57-1e788fca85dc", "type": "concept", "title": "Contraindications, comorbidity, polypharmacy, and complexity"}, {"id": "70165348-25b7-4544-94c1-af11e04c114f", "type": "concept", "title": "Documentation of preference-sensitive decisions"}], "description": "Recommendations guide but do not erase clinical judgment; decision-making must account for benefits, harms, burdens, resources, and what matters to the person."}, {"id": "a8d5b130-af61-457a-b0b5-5f2c340dd59e", "type": "subtopic", "title": "Local adoption and adaptation", "children": [{"id": "c372244b-e28b-4ce9-9fca-c935ea34a4ef", "type": "concept", "title": "Local policy and order-set review"}, {"id": "6edc7e8c-f777-4173-9316-b7079932a44a", "type": "concept", "title": "Resource and workflow assessment"}, {"id": "457588fc-dbf2-4304-a264-31fa6a782a7b", "type": "concept", "title": "Cultural and linguistic adaptation"}, {"id": "a5189ad6-be63-443b-b6dd-b9376225fff3", "type": "concept", "title": "Stakeholder approval and governance"}, {"id": "0bb86abf-d972-4323-adc6-d376e3472b62", "type": "concept", "title": "Monitoring exceptions, fidelity, and unintended consequences"}], "description": "Teams should adapt implementation to context while protecting the recommendation's core evidence-based function."}]}, {"id": "47545d85-4e60-44b9-95b0-bab8098f0c49", "type": "topic", "title": "Ethics, Equity, and Patient/Community Partnership", "description": "Ethically sound evidence work protects rights and dignity while addressing whose questions are studied, whose outcomes count, and who benefits from change.", "children": [{"id": "107e8659-73d2-4b35-b1bd-a87ea742a34e", "type": "subtopic", "title": "Research ethics and oversight", "children": [{"id": "d0538956-72d2-4c47-b95e-537eed2c6aa4", "type": "concept", "title": "Respect for persons, beneficence, nonmaleficence, and justice"}, {"id": "7e203c82-e26f-476e-9ff8-350f604ff783", "type": "concept", "title": "Informed consent, assent, capacity, and therapeutic misconception"}, {"id": "40e27d80-8aef-4de4-882f-1ba115e2bbdd", "type": "concept", "title": "Privacy, confidentiality, data governance, and secondary use"}, {"id": "758e834e-73f6-4531-a912-1cedf32912a2", "type": "concept", "title": "IRB/research ethics board review and exempt/minimal-risk concepts"}, {"id": "c7f1949b-3390-4f67-88fd-e5f383e9bae1", "type": "concept", "title": "Research integrity, authorship, misconduct, and conflicts of interest"}], "description": "Ethical principles guide study design, recruitment, consent, data use, and the fair distribution of risks and benefits."}, {"id": "7241cf97-2520-46ed-9752-fddce63874b6", "type": "subtopic", "title": "Equity-centered evidence", "children": [{"id": "c58dcb37-d10e-4a81-85f7-e9460a9e135b", "type": "concept", "title": "Structural and social determinants of health"}, {"id": "a54b8e7b-7568-44ee-86c7-475b353a3596", "type": "concept", "title": "Race, ethnicity, sex, gender, disability, language, geography, and socioeconomic position"}, {"id": "1c01770d-ef9f-4e03-82e0-dced9c8cdde3", "type": "concept", "title": "Algorithmic and measurement bias"}, {"id": "bdaa297f-429e-4e28-ac21-b1e653c9d140", "type": "concept", "title": "Intersectionality and disaggregated outcomes"}, {"id": "5d93175a-ce2c-4d00-9331-d0d15e7fe876", "type": "concept", "title": "Culturally safe, trauma-informed, and anti-oppressive approaches"}], "description": "Evidence can obscure inequity when samples, measures, comparisons, and implementation plans fail to represent structural conditions and diverse experiences."}, {"id": "3bedfeb3-1d7a-4dea-8f21-1e29f533ff36", "type": "subtopic", "title": "Patient and community engagement", "children": [{"id": "c77e5be4-4eec-495a-9f2f-faae1761fa39", "type": "concept", "title": "Co-design of questions and outcomes"}, {"id": "ef780949-6d6f-44e2-8cc1-8d201eeac910", "type": "concept", "title": "Advisory roles, governance, compensation, and power sharing"}, {"id": "8be9865a-987d-40dd-bb89-28641d726dcd", "type": "concept", "title": "Community-based participatory principles"}, {"id": "b4174d83-3b41-450b-bc1a-268e3776a07f", "type": "concept", "title": "Accessible consent and communication"}, {"id": "c55a7893-6d86-47c4-8fcb-fcd11505f157", "type": "concept", "title": "Returning results and maintaining trust"}], "description": "Partnership improves relevance, acceptability, interpretation, and legitimacy when people with lived experience have meaningful influence rather than symbolic roles."}]}, {"id": "e89cbb5f-e45c-4eff-9b5f-75fb42d1589c", "type": "topic", "title": "EBP Models, Implementation Science, and Change Leadership", "description": "Evidence does not implement itself. This section provides structured models and leadership tools for understanding context, selecting strategies, and supporting reliable behavior and system change.", "children": [{"id": "81622d8c-3f02-46b4-81dd-df1d15a90060", "type": "subtopic", "title": "EBP process models", "children": [{"id": "6f282323-0202-4f76-9da4-1c2e411a5042", "type": "concept", "title": "Iowa Model"}, {"id": "19445599-6afb-4c73-846b-ea1b409da89b", "type": "concept", "title": "Johns Hopkins EBP model"}, {"id": "2fa60efa-b18b-4e66-8954-3afec55c631e", "type": "concept", "title": "JBI evidence implementation approach"}, {"id": "604bea70-ed5f-450b-94c5-3a781b12c498", "type": "concept", "title": "Stetler model"}, {"id": "70720a1a-fcdf-4c6d-85fb-0522da658d26", "type": "concept", "title": "Ask–acquire–appraise–apply–assess cycle and model selection"}], "description": "Models create a shared route from inquiry to sustained practice and help teams avoid jumping directly from an article to a policy."}, {"id": "a839b5bb-312e-4107-9f2f-d1f5daa11685", "type": "subtopic", "title": "Implementation determinants and strategies", "children": [{"id": "c8fd2c3a-587a-4956-9d5d-1a7d72dfd135", "type": "concept", "title": "Individual, intervention, inner-setting, outer-setting, and process determinants"}, {"id": "9000a758-fa16-48b1-9b14-dd14c766c79d", "type": "concept", "title": "Readiness, climate, leadership, resources, and workflow"}, {"id": "e08f6326-bd7b-4578-b6ce-5ffb88864f1d", "type": "concept", "title": "Education, audit and feedback, reminders, facilitation, champions, and opinion leaders"}, {"id": "7c7c3869-76a5-4d0e-ba4a-18e498002c50", "type": "concept", "title": "Tailoring, adaptation, and fidelity"}, {"id": "0321cc97-990f-4d50-abed-329904e0db31", "type": "concept", "title": "Graduate extension: logic models, implementation mapping, and strategy specification"}], "description": "Teams improve their odds of success by diagnosing barriers and facilitators, then matching active strategies to the causes of the evidence-practice gap."}, {"id": "c81b6582-63c1-4cb6-9670-7f3f830a5373", "type": "subtopic", "title": "Change leadership and interprofessional practice", "children": [{"id": "1fd07379-81b8-4aff-8e79-65f1ce895bf8", "type": "concept", "title": "Stakeholder and power-interest mapping"}, {"id": "0d2ac9e2-6929-45ec-bcf7-e7b6f862a895", "type": "concept", "title": "Interprofessional roles and shared governance"}, {"id": "db562fda-2aba-4e41-9ad3-85dfd01417fb", "type": "concept", "title": "Change narratives and communication plans"}, {"id": "fd3e3ed2-e4c8-4360-8ab7-3bbf870470fc", "type": "concept", "title": "Resistance as data; conflict and negotiation"}, {"id": "7ff3abec-1920-4c87-8982-c2f6a946ebc9", "type": "concept", "title": "Just culture, learning systems, and leadership behaviors"}], "description": "Sustainable change requires psychological safety, coalition building, role clarity, communication, and attention to competing priorities."}]}, {"id": "1fc880c7-ef60-4162-ba69-65f5b98c5e46", "type": "topic", "title": "Translation, Evaluation, Informatics, and Responsible AI", "description": "Translation connects implementation activities to measurable outcomes and learning. Digital systems can accelerate evidence use, but they also introduce workflow, privacy, bias, and automation risks.", "children": [{"id": "be47e36d-2129-4efc-9ab1-3f7144e71c76", "type": "subtopic", "title": "Implementation and outcome evaluation", "children": [{"id": "102ac180-8832-4459-857e-177e4ea0748d", "type": "concept", "title": "Structure, process, outcome, and balancing measures"}, {"id": "a00886d3-4826-47b5-ba9d-93415e414032", "type": "concept", "title": "Implementation outcomes: acceptability, adoption, appropriateness, feasibility, fidelity, cost, penetration, sustainment"}, {"id": "21d8ad34-dd64-4808-ad42-ec070f4d9db8", "type": "concept", "title": "Operational definitions, data sources, collection frequency, and data quality"}, {"id": "0b4d8aab-5237-4898-b814-0fd0376e5524", "type": "concept", "title": "Baseline, targets, benchmarks, and stratification"}, {"id": "71a91811-7a6f-4bd5-8685-6bb84bd9c301", "type": "concept", "title": "Logic models and contribution versus causal attribution"}], "description": "A useful evaluation distinguishes whether a practice was implemented from whether it improved care and checks for unintended effects."}, {"id": "eb742085-5400-40db-9157-f958d59ca230", "type": "subtopic", "title": "QI analytics and learning over time", "children": [{"id": "23b40c2f-dfd0-4424-b65d-618892879b53", "type": "concept", "title": "Plan–Do–Study–Act cycles"}, {"id": "f30d95e8-6bea-4195-bce6-7cbd79efd29d", "type": "concept", "title": "Run charts and control-chart concepts"}, {"id": "6aac72b9-fa18-4a43-ac6f-3d21cc677d93", "type": "concept", "title": "Audit and feedback"}, {"id": "55f57626-518f-4f97-84d5-ed2193594aef", "type": "concept", "title": "Small tests, iterative adaptation, and documentation"}, {"id": "69abc9bc-68ef-4b4f-8e76-9158846d6d55", "type": "concept", "title": "Patient safety signals and escalation thresholds"}], "description": "Time-ordered data helps teams distinguish common variation from meaningful change and supports rapid learning during implementation."}, {"id": "1442f6b2-cd4f-4b9d-a3c8-addb6340588b", "type": "subtopic", "title": "Informatics and responsible AI", "children": [{"id": "a223566e-2061-44fe-a1ab-ea014b3a2bc6", "type": "concept", "title": "EHR data provenance, interoperability, and clinical decision support"}, {"id": "cab16f14-df42-4609-a815-278721f383cf", "type": "concept", "title": "Data dictionaries, dashboards, and alert fatigue"}, {"id": "d65d6387-e6d8-4807-a46b-70b25a07add1", "type": "concept", "title": "Automation bias, hallucination, and model drift"}, {"id": "0df7e99b-7453-4f31-9117-94766dbf4f2f", "type": "concept", "title": "Bias evaluation across patient groups"}, {"id": "f0336fe5-b6ee-47b8-b601-7355d072863a", "type": "concept", "title": "Human oversight, protected data, disclosure, citation verification, and audit trails"}], "description": "Technology should augment professional judgment while preserving verification, accountability, privacy, transparency, and equitable performance."}]}, {"id": "6b6a6210-f576-4f68-8760-3b6929bdac32", "type": "topic", "title": "Dissemination, Sustainability, and Knowledge Mobilization", "description": "The final section turns sound analysis into action. Learners tailor messages to audiences, plan for sustainment and spread, and make evidence products transparent enough to support future updating.", "children": [{"id": "e7b42d8f-847f-4c5c-b23b-fa7ec5e9e3a2", "type": "subtopic", "title": "Scholarly and professional dissemination", "children": [{"id": "bdfa03d5-b0a3-4ece-8fe1-04fd951ff9bf", "type": "concept", "title": "Abstracts, posters, manuscripts, podium presentations, and journal clubs"}, {"id": "230c34ac-270c-4986-9bf5-a69e69c91095", "type": "concept", "title": "Executive briefs, dashboards, policy briefs, and clinical pathways"}, {"id": "b5c77f9c-cd86-4f78-9a96-7bc62fdd55a0", "type": "concept", "title": "Reporting guidelines such as CONSORT, STROBE, PRISMA, COREQ, SQUIRE, and relevant extensions"}, {"id": "d313ecfc-d653-4432-978c-21324bd3dad6", "type": "concept", "title": "Authorship, contributorship, conflicts, and data availability"}, {"id": "e4cf1717-c727-451c-ab3c-7af948e2ad30", "type": "concept", "title": "Peer review, preprints, corrections, retractions, and post-publication learning"}], "description": "Different audiences need different levels of detail, but every format should preserve the evidence's strength, uncertainty, limitations, and implications."}, {"id": "c4f7f106-8f5f-4df0-80b2-b7d6a969fbe1", "type": "subtopic", "title": "Patient and public communication", "children": [{"id": "f234a73c-09b0-4584-85cb-0c2506e36354", "type": "concept", "title": "Plain language and health literacy"}, {"id": "6bf2a334-0613-4ebb-b421-d3bcf16eea61", "type": "concept", "title": "Absolute versus relative risk communication"}, {"id": "905c1d3d-7248-4554-b670-8307650d744d", "type": "concept", "title": "Visual displays and natural frequencies"}, {"id": "e1e4a299-68ce-4e29-b86c-9c6e173589f9", "type": "concept", "title": "Teach-back and language access"}, {"id": "4756ce21-23df-4465-8fa2-d56406af7df4", "type": "concept", "title": "Misinformation, uncertainty, and respectful correction"}], "description": "Accessible communication supports shared decisions and trust by explaining benefits, harms, uncertainty, and options without manipulation."}, {"id": "9cc51bc6-31ff-46ed-9e21-4eae3cde0934", "type": "subtopic", "title": "Sustainability, spread, and updating", "children": [{"id": "2fb17569-3754-4fc8-b1bf-423bde32222a", "type": "concept", "title": "Sustainment determinants and ownership"}, {"id": "3dc9fc50-60b7-4a98-8702-f61f9ef29c59", "type": "concept", "title": "Integration into workflow, policy, onboarding, and competency systems"}, {"id": "f21da2db-d8b8-4324-ad8e-2c77287215d4", "type": "concept", "title": "Resource use, budget impact, and de-implementation of low-value care"}, {"id": "dfe58c95-b3bc-4ab2-b715-39fefe56bd4a", "type": "concept", "title": "Adaptation for spread while preserving core functions"}, {"id": "472d11b1-a176-44ca-a8b2-22935c0ab39f", "type": "concept", "title": "Monitoring evidence updates, sunset criteria, and living products"}], "description": "A successful launch is not the endpoint; practices must remain feasible, effective, equitable, and aligned with evolving evidence."}]}, {"id": "2c3a8329-98a6-42f8-9fb0-441ea642f0a8", "type": "topic", "title": "Capstone: Evidence-to-Practice Project Blueprint", "description": "The capstone integrates the entire course into a decision-ready proposal. It may be based on a real practice concern, but learners must not collect identifiable patient data or initiate a change without institutional authorization and appropriate oversight.", "children": [{"id": "9675c0b9-3046-4d7d-b465-666da548a90d", "type": "subtopic", "title": "Define", "children": [{"id": "98e826f4-99e1-4d2b-80fd-d725a048ac8e", "type": "concept", "title": "Practice problem and significance"}, {"id": "30715ec5-6b9a-4532-be6f-56e82d5a867f", "type": "concept", "title": "Stakeholder-validated question"}, {"id": "ced1a939-3210-4a9a-b412-50177056f56d", "type": "concept", "title": "Current-state data and equity implications"}]}, {"id": "f661edaa-adea-4a9a-944e-72cee1d813a3", "type": "subtopic", "title": "Discover", "children": [{"id": "fda2fe76-8e6d-45d7-ac14-1a65adefd96a", "type": "concept", "title": "Reproducible search"}, {"id": "a559f431-1aea-4ffa-afec-4da38c44195d", "type": "concept", "title": "Evidence table and critical appraisal"}, {"id": "c99134dc-4244-4888-8cb2-4ee09af7f25e", "type": "concept", "title": "Certainty, guideline, and applicability synthesis"}]}, {"id": "ab6e784e-d331-495b-bc8e-03ea33ae2491", "type": "subtopic", "title": "Design", "children": [{"id": "76a6d5ae-0e1b-4e59-85fb-ebcbb3831a53", "type": "concept", "title": "Recommendation and rationale"}, {"id": "a0aa248d-4b03-4846-ab96-9e9218085964", "type": "concept", "title": "Model, determinants, and implementation strategies"}, {"id": "43e5425b-f3d3-44e8-aac7-6606b38b4581", "type": "concept", "title": "Ethics, engagement, informatics, and resource plan"}]}, {"id": "6c03b912-0306-4d7c-8a0d-6668465ff310", "type": "subtopic", "title": "Evaluate", "children": [{"id": "a7d9f805-b9dc-4aa4-88c9-e0b52999a705", "type": "concept", "title": "Process, outcome, balancing, implementation, and equity measures"}, {"id": "e060f98d-6d71-4a86-a2fd-d5557121bfbb", "type": "concept", "title": "Data source, timing, analysis, and feedback plan"}, {"id": "6fb0e799-dab2-44b1-93fd-ce4be28350b2", "type": "concept", "title": "Sustainment, spread, de-implementation, and updating criteria"}]}, {"id": "6ab01f15-8c6b-4fb9-a582-762242fe4232", "type": "subtopic", "title": "Disseminate", "children": [{"id": "8592be3c-de7e-431e-bbfa-f32821719e74", "type": "concept", "title": "Patient-facing product"}, {"id": "77487cb5-5619-4838-89ce-872ff7cb04ee", "type": "concept", "title": "Clinical/leadership brief"}, {"id": "dd56d9a2-9c87-410c-b044-16c5c130d2ca", "type": "concept", "title": "Scholarly poster or presentation"}]}]}], "dbBacked": true}$nrebpjson$::jsonb,
  true,
  false,
  'course',
  'public'
where not exists (
  select 1 from public.learning_paths where slug = 'nursing-research-and-evidence-based-practice'
);

update public.learning_paths
set
  title = 'Nursing Research and Evidence-Based Practice',
  goal = 'Nursing Research and Evidence-Based Practice',
  summary = 'This integrated course develops the knowledge, judgment, and practical skills nurses need to ask answerable clinical questions, find and critically appraise research, integrate evidence with clinical expertise and patient values, and lead ethical, equitable improvements in care. BSN learners build confident research literacy and contribute to evidence-based change; MSN learners additionally evaluate complex bodies of evidence, select implementation strategies, measure outcomes, and lead dissemination.',
  data = $nrebpjson${"slug": "nursing-research-and-evidence-based-practice", "title": "Nursing Research and Evidence-Based Practice", "description": "This integrated course develops the knowledge, judgment, and practical skills nurses need to ask answerable clinical questions, find and critically appraise research, integrate evidence with clinical expertise and patient values, and lead ethical, equitable improvements in care. BSN learners build confident research literacy and contribute to evidence-based change; MSN learners additionally evaluate complex bodies of evidence, select implementation strategies, measure outcomes, and lead dissemination.", "topics": [{"id": "e21b2a1e-363c-4e86-b5d7-2b096cd0b1f8", "type": "topic", "title": "Foundations of Nursing Research and Evidence-Based Practice", "description": "This section establishes why disciplined inquiry is a professional nursing responsibility and how research, evidence-based practice, quality improvement, and implementation science work together without being interchangeable.", "children": [{"id": "c2d4f684-8b9c-4cfd-a880-eb0c2d68ef50", "type": "subtopic", "title": "The research process", "children": [{"id": "281fa719-86a2-4184-a955-5a930cc3952b", "type": "concept", "title": "Problem identification and significance"}, {"id": "9079b69e-fad9-446f-b474-f7745266a6c9", "type": "concept", "title": "Purpose statements, aims, questions, and hypotheses"}, {"id": "5b9a7326-de6d-4361-89bc-a5747c86615e", "type": "concept", "title": "Conceptual and theoretical frameworks"}, {"id": "51719220-b525-4558-b8b3-2e0b949888b4", "type": "concept", "title": "Literature review, design, data collection, analysis, interpretation, and reporting"}, {"id": "c157e2d4-c634-4faf-9233-04b6a7baed57", "type": "concept", "title": "Replication, reproducibility, transparency, and open-science principles"}], "description": "The research process turns uncertainty into a systematic, transparent investigation that can generate trustworthy and transferable knowledge."}, {"id": "a6e4d580-3f63-4cd6-aa06-ffe7f27ff4a5", "type": "subtopic", "title": "Evidence-based practice as clinical reasoning", "children": [{"id": "8a9b241c-a6e4-4307-89f7-2d5db104c75c", "type": "concept", "title": "Best research evidence"}, {"id": "0bfaebf7-bb39-4912-b0b2-be56637f2330", "type": "concept", "title": "Clinical expertise and professional judgment"}, {"id": "5dc964cd-0f59-4433-84ec-0316472d7816", "type": "concept", "title": "Patient values, goals, culture, and preferences"}, {"id": "c288cc40-5f97-414f-88a6-ff03f76a1e41", "type": "concept", "title": "Local data, resources, feasibility, and context"}, {"id": "383057d7-4710-4618-95e6-3635b5d89640", "type": "concept", "title": "Shared decision-making and person-centered care"}], "description": "EBP is a decision process—not simply following a paper—that integrates best available evidence with expertise, patient goals, and the realities of a care setting."}, {"id": "b3508f7a-0edc-472b-8d87-8cd000bfa7ec", "type": "subtopic", "title": "Research, EBP, QI, and implementation science", "children": [{"id": "74a0bc05-6570-4158-8fe5-204a74b1d081", "type": "concept", "title": "Knowledge generation versus local improvement"}, {"id": "a51e0fec-26d4-4b3d-be7c-cbbb47f74ff6", "type": "concept", "title": "QI cycles and process control"}, {"id": "88be5a53-6d22-4c14-8598-68fadd4ee024", "type": "concept", "title": "Evidence translation and implementation research"}, {"id": "fc48a1fc-ca7e-40bf-a831-fda459eed437", "type": "concept", "title": "Program evaluation and operational analytics"}, {"id": "9caa01fc-5abf-491a-bb9d-2fb8661da0e9", "type": "concept", "title": "When activities overlap and when consultation or review is needed"}], "description": "Knowing the distinctions prevents inappropriate claims, clarifies oversight, and helps teams choose methods that match their actual purpose."}]}, {"id": "6d89f863-7290-43c7-b5ed-07005abeb064", "type": "topic", "title": "Clinical Questions, Evidence Searching, and Information Stewardship", "description": "Strong evidence work begins with an answerable question and a search that another person could understand, reproduce, and update. This section builds efficient inquiry habits and guards against convenience-based evidence selection.", "children": [{"id": "d4693e7a-11a7-4bce-a22c-0940af28113a", "type": "subtopic", "title": "Question formulation", "children": [{"id": "2117bef8-9cea-4d59-9fba-26e66fcdbc91", "type": "concept", "title": "PICOT for interventions and therapy"}, {"id": "94814ec1-92e0-4c18-ac4c-80077516f702", "type": "concept", "title": "PEO/SPIDER for experiences and qualitative inquiry"}, {"id": "200fdb28-fb44-4f95-9070-35e61d4e581d", "type": "concept", "title": "Etiology, harm, diagnosis, prognosis, and prevalence questions"}, {"id": "cd4298b4-6427-4081-b3db-8ed6b2967d85", "type": "concept", "title": "Foreground versus background questions"}, {"id": "cadd8c46-0649-4fd9-966c-ec847afc09b4", "type": "concept", "title": "Outcome prioritization with patients and stakeholders"}], "description": "A structured question makes the population, uncertainty, outcomes, and decision visible so the search and appraisal remain clinically focused."}, {"id": "5c916326-c1e3-4a0e-8148-488a33cfcb61", "type": "subtopic", "title": "Database searching", "children": [{"id": "56106d63-6d16-404d-8100-6abea98cd7aa", "type": "concept", "title": "PubMed/MEDLINE and CINAHL roles"}, {"id": "9636009b-620e-4376-9c9e-581a343b1dca", "type": "concept", "title": "Subject headings and text words"}, {"id": "154dd5c7-45ab-47dd-bb9c-c73bc8554192", "type": "concept", "title": "Boolean logic, phrase searching, truncation, and proximity"}, {"id": "8a471e78-c254-495b-abfd-d55866875790", "type": "concept", "title": "Filters, limits, citation chaining, and grey literature"}, {"id": "fb8bb8ad-a74b-4baa-93ec-ecf404055425", "type": "concept", "title": "Search documentation and peer review"}], "description": "Searching is an iterative reasoning task that combines controlled vocabulary, keywords, logic, and database-specific translation."}, {"id": "62b47397-6091-410a-bea4-60d221e1843b", "type": "subtopic", "title": "Evidence and citation management", "children": [{"id": "c8762c85-3c24-4006-90ad-77dcfd23a8b6", "type": "concept", "title": "Citation managers and deduplication"}, {"id": "f79a36e5-90a8-4c6e-9985-b8b4ff6e3947", "type": "concept", "title": "Eligibility criteria and screening logs"}, {"id": "4824d207-d98b-4f68-8684-8433b4fe6f3b", "type": "concept", "title": "Evidence tables and annotated bibliographies"}, {"id": "68ba5646-2c00-4ea8-a2bf-a74d4dcf186e", "type": "concept", "title": "Persistent identifiers, versions, and retractions"}, {"id": "2965850d-5c4c-4d22-b987-c7c6014ba206", "type": "concept", "title": "Copyright, licensing, data privacy, and information security"}], "description": "Organized records reduce duplication, support transparent screening, and preserve a defensible path from question to included evidence."}]}, {"id": "e2b72e79-fa6f-48f8-b73b-8e13fdf04b0c", "type": "topic", "title": "Quantitative Research Designs, Sampling, and Measurement", "description": "Quantitative research estimates relationships, differences, diagnostic accuracy, and intervention effects. Learners focus on how design choices shape causal claims, bias, precision, and applicability.", "children": [{"id": "0242ba97-3b5e-46a7-ae0b-0329fa00f03f", "type": "subtopic", "title": "Experimental and quasi-experimental designs", "children": [{"id": "86326a5c-4945-4b81-98d3-3efd29ccbbb4", "type": "concept", "title": "Randomized controlled trials and allocation concealment"}, {"id": "ac558a46-1ae1-41a9-96d9-e94ff49ee7d2", "type": "concept", "title": "Blinding, comparators, contamination, and co-interventions"}, {"id": "f5065867-42a3-4b66-a342-db9351b0c902", "type": "concept", "title": "Pragmatic, cluster, crossover, and stepped-wedge trials"}, {"id": "06037318-50c0-4495-afe0-d34dacfc7699", "type": "concept", "title": "Quasi-experimental, interrupted time-series, and pre/post designs"}, {"id": "9b7fd88e-f307-4aa0-9740-11d888f3792c", "type": "concept", "title": "Protocol deviations, attrition, and intention-to-treat reasoning"}], "description": "Intervention designs test whether changing an exposure or practice produces a meaningful outcome, with varying protection against confounding."}, {"id": "51df8daf-dafd-4517-a760-bd643837bdb5", "type": "subtopic", "title": "Observational designs", "children": [{"id": "7787a96c-5d20-45f0-a061-c088d78227d1", "type": "concept", "title": "Cohort, case-control, cross-sectional, and ecological designs"}, {"id": "7bc8b85c-58e2-4082-81ee-2aa241e08764", "type": "concept", "title": "Prospective versus retrospective data"}, {"id": "29da5ad2-fdbf-4fd9-8c6b-1ecc03c3edec", "type": "concept", "title": "Confounding, selection bias, information bias, and reverse causation"}, {"id": "a1bdcc2c-bf35-4bf1-b70a-326958ee7f85", "type": "concept", "title": "Risk adjustment and causal diagrams as conceptual tools"}, {"id": "4fdd0b99-8c3a-40e8-b899-09f733879314", "type": "concept", "title": "Applicability to nursing populations and settings"}], "description": "Observational studies are essential for prevalence, prognosis, risk, harm, and real-world questions, but their conclusions depend heavily on bias control."}, {"id": "c28b7ed4-55c3-4205-9483-4f331dba64ab", "type": "subtopic", "title": "Sampling and measurement", "children": [{"id": "1ab42805-ba2e-44ae-97ad-d3ec916053e9", "type": "concept", "title": "Probability and nonprobability sampling"}, {"id": "136f97ea-fe1e-4871-8c8e-ef08e4ae6708", "type": "concept", "title": "Recruitment, inclusion, exclusion, and retention"}, {"id": "301c9ada-8f6e-46f2-87ca-38f5f3a05272", "type": "concept", "title": "Power, sample size, precision, and feasibility"}, {"id": "3e34ca5d-1b20-47a4-b6d9-cc51a4629b0d", "type": "concept", "title": "Reliability, validity, responsiveness, and measurement error"}, {"id": "8c3a7c65-3daa-4636-9833-356dcb2e2a17", "type": "concept", "title": "Patient-reported outcomes, clinical measures, and meaningful thresholds"}], "description": "A result is only as useful as the people represented and the measures used to describe them."}]}, {"id": "2dc773be-98ef-439d-a1d8-85a98a76e631", "type": "topic", "title": "Statistical Reasoning and Data Interpretation", "description": "Nurses need statistical literacy to judge claims and explain uncertainty—not to worship a threshold. This section emphasizes interpretation, clinical importance, and transparent communication.", "children": [{"id": "ec20b250-474e-42ad-8b72-ee36a4ebb1ce", "type": "subtopic", "title": "Describing data", "children": [{"id": "05b348ee-24eb-43aa-94d7-292b0198fb09", "type": "concept", "title": "Variable types and distributions"}, {"id": "51a6b36a-8a6c-4439-8007-cb866543ae99", "type": "concept", "title": "Mean, median, mode, range, variance, and standard deviation"}, {"id": "f7586266-9814-4114-b8f6-c9ea5e018fa9", "type": "concept", "title": "Rates, ratios, proportions, incidence, and prevalence"}, {"id": "c42b0b30-a751-4cf7-83da-b5cffbd5f2a4", "type": "concept", "title": "Tables, histograms, box plots, and data visualization"}, {"id": "63282cd1-b085-4281-afa6-e86ca170cebd", "type": "concept", "title": "Missing data, outliers, data quality, and denominator integrity"}], "description": "Descriptive statistics reveal the shape, center, spread, and quality of clinical data before inferential conclusions are attempted."}, {"id": "3762b786-02e1-4ac3-9aa6-9f5f9cbccce7", "type": "subtopic", "title": "Estimating effects and uncertainty", "children": [{"id": "3024d279-dc86-4729-9915-c8d0ce823a2a", "type": "concept", "title": "Risk ratio, odds ratio, hazard ratio, and mean difference"}, {"id": "4d73a203-20fa-4588-ac3a-8e7fd7b89d0d", "type": "concept", "title": "Absolute risk difference and number needed to treat/harm"}, {"id": "dbcb7256-1133-4ab0-b6a2-fdfd8bb5dc5d", "type": "concept", "title": "Confidence intervals and standard errors"}, {"id": "da6c7d96-46c9-4638-a6bd-9f79c90a56ce", "type": "concept", "title": "P values, Type I/II errors, multiplicity, and power"}, {"id": "ca04c01c-eba0-487f-ac3e-091fb68427bb", "type": "concept", "title": "Statistical versus clinical significance"}], "description": "Effect estimates and confidence intervals show magnitude and precision, helping readers move beyond the binary language of statistical significance."}, {"id": "6c2d58e5-1beb-4cd2-b80d-7862a771a9e8", "type": "subtopic", "title": "Common analyses and responsible interpretation", "children": [{"id": "e2760e45-b686-4df4-9b4f-a74c29dbae9d", "type": "concept", "title": "t tests, ANOVA, chi-square, correlation, and regression"}, {"id": "611814fa-ff83-40d5-9fa6-f029de05cf92", "type": "concept", "title": "Adjusted versus unadjusted estimates"}, {"id": "89b1adf5-b135-49d8-b7e7-6f715682bf64", "type": "concept", "title": "Interaction, subgroup analysis, and confounding"}, {"id": "91975ee9-571a-4845-820f-409bb36f1bb1", "type": "concept", "title": "Survival analysis and time-to-event basics"}, {"id": "b9a9a504-e810-4231-a944-c4f7e3fbe96a", "type": "concept", "title": "Graduate extension: model fit, assumptions, sensitivity analysis, and reproducible code"}], "description": "Understanding what an analysis compares and assumes helps learners detect exaggerated, unsupported, or misleading claims."}]}, {"id": "7f77773c-7a51-4149-b6ef-a7d0ab552948", "type": "topic", "title": "Qualitative and Mixed-Methods Inquiry", "description": "Qualitative evidence makes experience, meaning, culture, workflow, and context visible. Mixed methods intentionally connects numerical patterns with explanatory depth to answer complex practice questions.", "children": [{"id": "647b1ae5-6846-4347-93b7-5e7dc3578b93", "type": "subtopic", "title": "Qualitative traditions and questions", "children": [{"id": "be11ab62-c702-49e3-b1fc-42dd1478b40b", "type": "concept", "title": "Phenomenology, grounded theory, ethnography, case study, and qualitative description"}, {"id": "fb9a3bf3-9e05-475f-9dc3-04a9043eb695", "type": "concept", "title": "Researcher positionality and reflexivity"}, {"id": "1af423e4-cf7e-4fea-b302-6cbe574a2ae9", "type": "concept", "title": "Purposive, theoretical, and snowball sampling"}, {"id": "2f1350e9-a447-4692-98ee-b043ebbbe746", "type": "concept", "title": "Saturation and information power"}, {"id": "e7c278a0-4a46-4937-99b6-66322961d4b9", "type": "concept", "title": "Interviews, focus groups, observation, documents, and digital data"}], "description": "Methodological traditions shape what counts as data, how participants are engaged, and what kind of knowledge a study can claim."}, {"id": "6ed7eac7-c4d3-4002-b1d1-baa645c79174", "type": "subtopic", "title": "Qualitative analysis and rigor", "children": [{"id": "8d352b96-8fee-4475-a50b-86909e57454b", "type": "concept", "title": "Coding, categorization, memoing, and theme development"}, {"id": "8c9d3e6b-c56e-48a8-afdb-47e651601986", "type": "concept", "title": "Inductive, deductive, and abductive reasoning"}, {"id": "1e39d659-6ba3-4169-9b5d-ab22170d8d09", "type": "concept", "title": "Credibility, dependability, confirmability, and transferability"}, {"id": "f6a87797-1455-4d3f-83ad-9b806ecbe0cc", "type": "concept", "title": "Triangulation, member reflection, audit trails, and negative cases"}, {"id": "3376944f-0477-4637-844d-ad44e29a846e", "type": "concept", "title": "Representation, quotation, confidentiality, and interpretive humility"}], "description": "Systematic analysis makes the path from raw accounts to interpretations visible and credible."}, {"id": "c155693f-f8f3-4b41-9c63-22ced680ab27", "type": "subtopic", "title": "Mixed-methods integration", "children": [{"id": "e8c61be6-30ef-48db-a95e-a2e5397f46a0", "type": "concept", "title": "Convergent, explanatory sequential, and exploratory sequential designs"}, {"id": "c7500794-d172-4681-90d7-9e37206ffc8a", "type": "concept", "title": "Connecting, building, merging, and embedding"}, {"id": "88b71ff0-6d78-44fd-b33d-1a2de548abe2", "type": "concept", "title": "Joint displays and meta-inferences"}, {"id": "3d8ba588-5aed-4bcc-8930-635b89aae87b", "type": "concept", "title": "Managing discordant findings"}, {"id": "650c5138-cc20-4b3d-8722-7e35d363e996", "type": "concept", "title": "Graduate extension: integration quality and mixed-methods legitimation"}], "description": "Mixed methods adds value only when qualitative and quantitative strands are deliberately connected and produce insight beyond parallel results."}]}, {"id": "ecfafb4c-4b37-4c93-ac5e-6e2f5fa9337d", "type": "topic", "title": "Critical Appraisal of Individual Studies", "description": "Critical appraisal asks whether a study is trustworthy, what it actually shows, and whether it helps with a specific decision. The goal is calibrated judgment rather than checklist completion.", "children": [{"id": "ccfc1dea-1157-4c33-8e37-fdba53a45ea3", "type": "subtopic", "title": "Validity and risk of bias", "children": [{"id": "a0c1daa6-29d3-4ebe-8729-d5858b43afa3", "type": "concept", "title": "Selection, performance, detection, attrition, and reporting bias"}, {"id": "d1b1d1b6-8e16-4ba1-9f9f-056482334a38", "type": "concept", "title": "Confounding and baseline imbalance"}, {"id": "c66171a5-fc35-4387-a488-a4fbb08846c3", "type": "concept", "title": "Measurement validity and outcome ascertainment"}, {"id": "56fcdd15-6e06-4304-91c0-d6856d6d91dc", "type": "concept", "title": "Selective outcomes, spin, protocol registration, and conflicts of interest"}, {"id": "323ee603-f80f-4c68-bb1d-70e7dadfa990", "type": "concept", "title": "Design-specific appraisal tools and domain-based judgments"}], "description": "Internal validity concerns whether the observed result is a credible estimate for the study participants."}, {"id": "cb919a03-06a1-435a-a769-46e0f0522f2b", "type": "subtopic", "title": "Results and precision", "children": [{"id": "586e5332-027c-4dfa-94db-4c7d9d3277e3", "type": "concept", "title": "Effect size and direction"}, {"id": "81b3232b-7ea8-44ed-9a11-81cbd998c45b", "type": "concept", "title": "Confidence intervals and imprecision"}, {"id": "36f4fa3c-53d3-404d-89ce-b65ea9e9c150", "type": "concept", "title": "Clinical importance and minimal important differences"}, {"id": "ba42d98e-1ae4-4209-bb47-1d25126f318c", "type": "concept", "title": "Harms, burden, and unintended effects"}, {"id": "09fd3ab9-a925-4c18-b728-b737dc6f28ee", "type": "concept", "title": "Qualitative richness, coherence, and supporting data"}], "description": "Learners translate statistical and qualitative findings into plain-language statements that preserve magnitude, uncertainty, and limitations."}, {"id": "4835ea21-76e0-48db-90d5-55fe3d5d6282", "type": "subtopic", "title": "Applicability and equity", "children": [{"id": "1a705777-3f3f-4ba6-b058-98ec143c125a", "type": "concept", "title": "Population and setting similarity"}, {"id": "d43c264a-fbc7-43fa-9b9f-bbdb7d52af57", "type": "concept", "title": "Feasibility, acceptability, cost, and workflow"}, {"id": "2304cb5e-ff8c-4a5c-950a-910b60f06d2e", "type": "concept", "title": "Patient goals and treatment burden"}, {"id": "a7a303b8-a067-4be4-afc0-27b8fd0d84b5", "type": "concept", "title": "Representation and subgroup credibility"}, {"id": "7b75ca4d-4b73-4382-b55a-28c5454f0509", "type": "concept", "title": "PROGRESS-Plus and equity-relevant applicability checks"}], "description": "External validity asks whether evidence fits the patient, population, team, setting, and resources involved in the decision."}]}, {"id": "81696df3-1b90-4800-b29f-ff687ee4a2f2", "type": "topic", "title": "Evidence Synthesis, Meta-analysis, and Certainty", "description": "No single study settles most practice questions. This section shows how systematic reviews assemble evidence, how meta-analysis combines estimates, and how certainty should constrain recommendations.", "children": [{"id": "344e213e-fe66-4da7-9810-1ebc16741ff7", "type": "subtopic", "title": "Systematic review methods", "children": [{"id": "c71b7e9d-84cc-4898-a8b8-aec694c4ecf5", "type": "concept", "title": "Protocol registration and reporting standards"}, {"id": "71df94c1-0799-43da-ab96-04abfbe61904", "type": "concept", "title": "Comprehensive searching and study selection"}, {"id": "88815e6f-fb44-4530-a308-7109ab3241e9", "type": "concept", "title": "Data extraction and duplicate processes"}, {"id": "20a2bd5d-d6ae-400f-82df-5e6a4e23e75a", "type": "concept", "title": "Risk-of-bias assessment across designs"}, {"id": "b58b1c0e-1833-42a6-af38-0351a159f425", "type": "concept", "title": "Narrative synthesis and transparent exclusions"}], "description": "A trustworthy review uses prespecified, reproducible methods to reduce bias in finding, selecting, appraising, and synthesizing studies."}, {"id": "290d30e0-78c0-4e2e-b475-1d6c7e7335e8", "type": "subtopic", "title": "Meta-analysis interpretation", "children": [{"id": "730aeb2f-f489-4cb3-bfcf-623d7302b489", "type": "concept", "title": "Forest plots, weights, and pooled effects"}, {"id": "7c10b077-69f9-432f-b021-b5f3effd9e1a", "type": "concept", "title": "Fixed-effect and random-effects models"}, {"id": "ba6fb880-238c-4e3e-8c79-dd6ed1bac0ea", "type": "concept", "title": "Clinical, methodological, and statistical heterogeneity"}, {"id": "e399b458-f403-4454-939d-262d5d9fcf99", "type": "concept", "title": "I², prediction intervals, subgroup and sensitivity analyses"}, {"id": "e62041ae-5d8d-4c64-b75d-7dfee6611a70", "type": "concept", "title": "Publication bias, small-study effects, and funnel plots"}], "description": "Meta-analysis increases precision when studies are sufficiently compatible, but a pooled number cannot repair biased or incomparable evidence."}, {"id": "8abd60c7-41a7-41e2-a252-abd31e111dd5", "type": "subtopic", "title": "Levels of evidence and certainty grading", "children": [{"id": "befad3ec-3d01-4d87-bf6a-dc2d264fa274", "type": "concept", "title": "Study-design hierarchies and their limits"}, {"id": "78068785-cfba-4209-a556-275da50738cf", "type": "concept", "title": "GRADE domains: risk of bias, inconsistency, indirectness, imprecision, publication bias"}, {"id": "fbfbd6ee-348e-4874-8661-437d9298bd7c", "type": "concept", "title": "Upgrading considerations for observational evidence"}, {"id": "b9db85e2-5d75-4a10-8c81-eeb5970f1760", "type": "concept", "title": "High, moderate, low, and very-low certainty"}, {"id": "1a16cc87-44a6-4121-b6fb-f6964c21358b", "type": "concept", "title": "Strength of recommendation versus certainty of evidence"}], "description": "Evidence hierarchies are useful shortcuts, while certainty frameworks support a more nuanced judgment across an entire body of evidence."}]}, {"id": "63ea74c4-5717-4149-9572-2d7cbb93bb07", "type": "topic", "title": "Clinical Practice Guidelines and Evidence-Based Decisions", "description": "Guidelines translate bodies of evidence into recommendations, but quality, currency, conflicts, feasibility, and patient values still require scrutiny before adoption.", "children": [{"id": "37da6a86-8e70-48f7-a89a-aa431ce31d0b", "type": "subtopic", "title": "Guideline development and appraisal", "children": [{"id": "7ded6d2d-d09a-462b-9b30-3b1748ca11e4", "type": "concept", "title": "Scope, stakeholder representation, and patient involvement"}, {"id": "08ba8736-625f-411e-8d73-6e18b693c1bc", "type": "concept", "title": "Systematic evidence review and evidence-to-decision frameworks"}, {"id": "05074449-c55e-4a25-b0d6-1edf3d21d250", "type": "concept", "title": "AGREE II domains"}, {"id": "304081ff-7723-4bd4-9601-7a575ecbbc61", "type": "concept", "title": "Conflict-of-interest management and editorial independence"}, {"id": "0ae12ecf-bbee-47f5-ad60-8727a74f4a0b", "type": "concept", "title": "Currency, updating, and living guidelines"}], "description": "Credible guidelines connect transparent evidence review with multidisciplinary deliberation and explicit management of conflicts."}, {"id": "6e760475-eeac-4f9d-81c5-89b653ffd0bd", "type": "subtopic", "title": "From recommendation to decision", "children": [{"id": "c611463a-1c1c-4492-ba1b-b4b6dc4a7fa7", "type": "concept", "title": "Strong versus conditional recommendations"}, {"id": "1031be60-e8f0-4fd3-93bd-e49c4f99b843", "type": "concept", "title": "Shared decision-making and decision aids"}, {"id": "ad78009d-90da-426e-9637-fc45e486a2e9", "type": "concept", "title": "Absolute effects and baseline risk"}, {"id": "5f96afc6-d899-4bc1-8a57-1e788fca85dc", "type": "concept", "title": "Contraindications, comorbidity, polypharmacy, and complexity"}, {"id": "70165348-25b7-4544-94c1-af11e04c114f", "type": "concept", "title": "Documentation of preference-sensitive decisions"}], "description": "Recommendations guide but do not erase clinical judgment; decision-making must account for benefits, harms, burdens, resources, and what matters to the person."}, {"id": "a8d5b130-af61-457a-b0b5-5f2c340dd59e", "type": "subtopic", "title": "Local adoption and adaptation", "children": [{"id": "c372244b-e28b-4ce9-9fca-c935ea34a4ef", "type": "concept", "title": "Local policy and order-set review"}, {"id": "6edc7e8c-f777-4173-9316-b7079932a44a", "type": "concept", "title": "Resource and workflow assessment"}, {"id": "457588fc-dbf2-4304-a264-31fa6a782a7b", "type": "concept", "title": "Cultural and linguistic adaptation"}, {"id": "a5189ad6-be63-443b-b6dd-b9376225fff3", "type": "concept", "title": "Stakeholder approval and governance"}, {"id": "0bb86abf-d972-4323-adc6-d376e3472b62", "type": "concept", "title": "Monitoring exceptions, fidelity, and unintended consequences"}], "description": "Teams should adapt implementation to context while protecting the recommendation's core evidence-based function."}]}, {"id": "47545d85-4e60-44b9-95b0-bab8098f0c49", "type": "topic", "title": "Ethics, Equity, and Patient/Community Partnership", "description": "Ethically sound evidence work protects rights and dignity while addressing whose questions are studied, whose outcomes count, and who benefits from change.", "children": [{"id": "107e8659-73d2-4b35-b1bd-a87ea742a34e", "type": "subtopic", "title": "Research ethics and oversight", "children": [{"id": "d0538956-72d2-4c47-b95e-537eed2c6aa4", "type": "concept", "title": "Respect for persons, beneficence, nonmaleficence, and justice"}, {"id": "7e203c82-e26f-476e-9ff8-350f604ff783", "type": "concept", "title": "Informed consent, assent, capacity, and therapeutic misconception"}, {"id": "40e27d80-8aef-4de4-882f-1ba115e2bbdd", "type": "concept", "title": "Privacy, confidentiality, data governance, and secondary use"}, {"id": "758e834e-73f6-4531-a912-1cedf32912a2", "type": "concept", "title": "IRB/research ethics board review and exempt/minimal-risk concepts"}, {"id": "c7f1949b-3390-4f67-88fd-e5f383e9bae1", "type": "concept", "title": "Research integrity, authorship, misconduct, and conflicts of interest"}], "description": "Ethical principles guide study design, recruitment, consent, data use, and the fair distribution of risks and benefits."}, {"id": "7241cf97-2520-46ed-9752-fddce63874b6", "type": "subtopic", "title": "Equity-centered evidence", "children": [{"id": "c58dcb37-d10e-4a81-85f7-e9460a9e135b", "type": "concept", "title": "Structural and social determinants of health"}, {"id": "a54b8e7b-7568-44ee-86c7-475b353a3596", "type": "concept", "title": "Race, ethnicity, sex, gender, disability, language, geography, and socioeconomic position"}, {"id": "1c01770d-ef9f-4e03-82e0-dced9c8cdde3", "type": "concept", "title": "Algorithmic and measurement bias"}, {"id": "bdaa297f-429e-4e28-ac21-b1e653c9d140", "type": "concept", "title": "Intersectionality and disaggregated outcomes"}, {"id": "5d93175a-ce2c-4d00-9331-d0d15e7fe876", "type": "concept", "title": "Culturally safe, trauma-informed, and anti-oppressive approaches"}], "description": "Evidence can obscure inequity when samples, measures, comparisons, and implementation plans fail to represent structural conditions and diverse experiences."}, {"id": "3bedfeb3-1d7a-4dea-8f21-1e29f533ff36", "type": "subtopic", "title": "Patient and community engagement", "children": [{"id": "c77e5be4-4eec-495a-9f2f-faae1761fa39", "type": "concept", "title": "Co-design of questions and outcomes"}, {"id": "ef780949-6d6f-44e2-8cc1-8d201eeac910", "type": "concept", "title": "Advisory roles, governance, compensation, and power sharing"}, {"id": "8be9865a-987d-40dd-bb89-28641d726dcd", "type": "concept", "title": "Community-based participatory principles"}, {"id": "b4174d83-3b41-450b-bc1a-268e3776a07f", "type": "concept", "title": "Accessible consent and communication"}, {"id": "c55a7893-6d86-47c4-8fcb-fcd11505f157", "type": "concept", "title": "Returning results and maintaining trust"}], "description": "Partnership improves relevance, acceptability, interpretation, and legitimacy when people with lived experience have meaningful influence rather than symbolic roles."}]}, {"id": "e89cbb5f-e45c-4eff-9b5f-75fb42d1589c", "type": "topic", "title": "EBP Models, Implementation Science, and Change Leadership", "description": "Evidence does not implement itself. This section provides structured models and leadership tools for understanding context, selecting strategies, and supporting reliable behavior and system change.", "children": [{"id": "81622d8c-3f02-46b4-81dd-df1d15a90060", "type": "subtopic", "title": "EBP process models", "children": [{"id": "6f282323-0202-4f76-9da4-1c2e411a5042", "type": "concept", "title": "Iowa Model"}, {"id": "19445599-6afb-4c73-846b-ea1b409da89b", "type": "concept", "title": "Johns Hopkins EBP model"}, {"id": "2fa60efa-b18b-4e66-8954-3afec55c631e", "type": "concept", "title": "JBI evidence implementation approach"}, {"id": "604bea70-ed5f-450b-94c5-3a781b12c498", "type": "concept", "title": "Stetler model"}, {"id": "70720a1a-fcdf-4c6d-85fb-0522da658d26", "type": "concept", "title": "Ask–acquire–appraise–apply–assess cycle and model selection"}], "description": "Models create a shared route from inquiry to sustained practice and help teams avoid jumping directly from an article to a policy."}, {"id": "a839b5bb-312e-4107-9f2f-d1f5daa11685", "type": "subtopic", "title": "Implementation determinants and strategies", "children": [{"id": "c8fd2c3a-587a-4956-9d5d-1a7d72dfd135", "type": "concept", "title": "Individual, intervention, inner-setting, outer-setting, and process determinants"}, {"id": "9000a758-fa16-48b1-9b14-dd14c766c79d", "type": "concept", "title": "Readiness, climate, leadership, resources, and workflow"}, {"id": "e08f6326-bd7b-4578-b6ce-5ffb88864f1d", "type": "concept", "title": "Education, audit and feedback, reminders, facilitation, champions, and opinion leaders"}, {"id": "7c7c3869-76a5-4d0e-ba4a-18e498002c50", "type": "concept", "title": "Tailoring, adaptation, and fidelity"}, {"id": "0321cc97-990f-4d50-abed-329904e0db31", "type": "concept", "title": "Graduate extension: logic models, implementation mapping, and strategy specification"}], "description": "Teams improve their odds of success by diagnosing barriers and facilitators, then matching active strategies to the causes of the evidence-practice gap."}, {"id": "c81b6582-63c1-4cb6-9670-7f3f830a5373", "type": "subtopic", "title": "Change leadership and interprofessional practice", "children": [{"id": "1fd07379-81b8-4aff-8e79-65f1ce895bf8", "type": "concept", "title": "Stakeholder and power-interest mapping"}, {"id": "0d2ac9e2-6929-45ec-bcf7-e7b6f862a895", "type": "concept", "title": "Interprofessional roles and shared governance"}, {"id": "db562fda-2aba-4e41-9ad3-85dfd01417fb", "type": "concept", "title": "Change narratives and communication plans"}, {"id": "fd3e3ed2-e4c8-4360-8ab7-3bbf870470fc", "type": "concept", "title": "Resistance as data; conflict and negotiation"}, {"id": "7ff3abec-1920-4c87-8982-c2f6a946ebc9", "type": "concept", "title": "Just culture, learning systems, and leadership behaviors"}], "description": "Sustainable change requires psychological safety, coalition building, role clarity, communication, and attention to competing priorities."}]}, {"id": "1fc880c7-ef60-4162-ba69-65f5b98c5e46", "type": "topic", "title": "Translation, Evaluation, Informatics, and Responsible AI", "description": "Translation connects implementation activities to measurable outcomes and learning. Digital systems can accelerate evidence use, but they also introduce workflow, privacy, bias, and automation risks.", "children": [{"id": "be47e36d-2129-4efc-9ab1-3f7144e71c76", "type": "subtopic", "title": "Implementation and outcome evaluation", "children": [{"id": "102ac180-8832-4459-857e-177e4ea0748d", "type": "concept", "title": "Structure, process, outcome, and balancing measures"}, {"id": "a00886d3-4826-47b5-ba9d-93415e414032", "type": "concept", "title": "Implementation outcomes: acceptability, adoption, appropriateness, feasibility, fidelity, cost, penetration, sustainment"}, {"id": "21d8ad34-dd64-4808-ad42-ec070f4d9db8", "type": "concept", "title": "Operational definitions, data sources, collection frequency, and data quality"}, {"id": "0b4d8aab-5237-4898-b814-0fd0376e5524", "type": "concept", "title": "Baseline, targets, benchmarks, and stratification"}, {"id": "71a91811-7a6f-4bd5-8685-6bb84bd9c301", "type": "concept", "title": "Logic models and contribution versus causal attribution"}], "description": "A useful evaluation distinguishes whether a practice was implemented from whether it improved care and checks for unintended effects."}, {"id": "eb742085-5400-40db-9157-f958d59ca230", "type": "subtopic", "title": "QI analytics and learning over time", "children": [{"id": "23b40c2f-dfd0-4424-b65d-618892879b53", "type": "concept", "title": "Plan–Do–Study–Act cycles"}, {"id": "f30d95e8-6bea-4195-bce6-7cbd79efd29d", "type": "concept", "title": "Run charts and control-chart concepts"}, {"id": "6aac72b9-fa18-4a43-ac6f-3d21cc677d93", "type": "concept", "title": "Audit and feedback"}, {"id": "55f57626-518f-4f97-84d5-ed2193594aef", "type": "concept", "title": "Small tests, iterative adaptation, and documentation"}, {"id": "69abc9bc-68ef-4b4f-8e76-9158846d6d55", "type": "concept", "title": "Patient safety signals and escalation thresholds"}], "description": "Time-ordered data helps teams distinguish common variation from meaningful change and supports rapid learning during implementation."}, {"id": "1442f6b2-cd4f-4b9d-a3c8-addb6340588b", "type": "subtopic", "title": "Informatics and responsible AI", "children": [{"id": "a223566e-2061-44fe-a1ab-ea014b3a2bc6", "type": "concept", "title": "EHR data provenance, interoperability, and clinical decision support"}, {"id": "cab16f14-df42-4609-a815-278721f383cf", "type": "concept", "title": "Data dictionaries, dashboards, and alert fatigue"}, {"id": "d65d6387-e6d8-4807-a46b-70b25a07add1", "type": "concept", "title": "Automation bias, hallucination, and model drift"}, {"id": "0df7e99b-7453-4f31-9117-94766dbf4f2f", "type": "concept", "title": "Bias evaluation across patient groups"}, {"id": "f0336fe5-b6ee-47b8-b601-7355d072863a", "type": "concept", "title": "Human oversight, protected data, disclosure, citation verification, and audit trails"}], "description": "Technology should augment professional judgment while preserving verification, accountability, privacy, transparency, and equitable performance."}]}, {"id": "6b6a6210-f576-4f68-8760-3b6929bdac32", "type": "topic", "title": "Dissemination, Sustainability, and Knowledge Mobilization", "description": "The final section turns sound analysis into action. Learners tailor messages to audiences, plan for sustainment and spread, and make evidence products transparent enough to support future updating.", "children": [{"id": "e7b42d8f-847f-4c5c-b23b-fa7ec5e9e3a2", "type": "subtopic", "title": "Scholarly and professional dissemination", "children": [{"id": "bdfa03d5-b0a3-4ece-8fe1-04fd951ff9bf", "type": "concept", "title": "Abstracts, posters, manuscripts, podium presentations, and journal clubs"}, {"id": "230c34ac-270c-4986-9bf5-a69e69c91095", "type": "concept", "title": "Executive briefs, dashboards, policy briefs, and clinical pathways"}, {"id": "b5c77f9c-cd86-4f78-9a96-7bc62fdd55a0", "type": "concept", "title": "Reporting guidelines such as CONSORT, STROBE, PRISMA, COREQ, SQUIRE, and relevant extensions"}, {"id": "d313ecfc-d653-4432-978c-21324bd3dad6", "type": "concept", "title": "Authorship, contributorship, conflicts, and data availability"}, {"id": "e4cf1717-c727-451c-ab3c-7af948e2ad30", "type": "concept", "title": "Peer review, preprints, corrections, retractions, and post-publication learning"}], "description": "Different audiences need different levels of detail, but every format should preserve the evidence's strength, uncertainty, limitations, and implications."}, {"id": "c4f7f106-8f5f-4df0-80b2-b7d6a969fbe1", "type": "subtopic", "title": "Patient and public communication", "children": [{"id": "f234a73c-09b0-4584-85cb-0c2506e36354", "type": "concept", "title": "Plain language and health literacy"}, {"id": "6bf2a334-0613-4ebb-b421-d3bcf16eea61", "type": "concept", "title": "Absolute versus relative risk communication"}, {"id": "905c1d3d-7248-4554-b670-8307650d744d", "type": "concept", "title": "Visual displays and natural frequencies"}, {"id": "e1e4a299-68ce-4e29-b86c-9c6e173589f9", "type": "concept", "title": "Teach-back and language access"}, {"id": "4756ce21-23df-4465-8fa2-d56406af7df4", "type": "concept", "title": "Misinformation, uncertainty, and respectful correction"}], "description": "Accessible communication supports shared decisions and trust by explaining benefits, harms, uncertainty, and options without manipulation."}, {"id": "9cc51bc6-31ff-46ed-9e21-4eae3cde0934", "type": "subtopic", "title": "Sustainability, spread, and updating", "children": [{"id": "2fb17569-3754-4fc8-b1bf-423bde32222a", "type": "concept", "title": "Sustainment determinants and ownership"}, {"id": "3dc9fc50-60b7-4a98-8702-f61f9ef29c59", "type": "concept", "title": "Integration into workflow, policy, onboarding, and competency systems"}, {"id": "f21da2db-d8b8-4324-ad8e-2c77287215d4", "type": "concept", "title": "Resource use, budget impact, and de-implementation of low-value care"}, {"id": "dfe58c95-b3bc-4ab2-b715-39fefe56bd4a", "type": "concept", "title": "Adaptation for spread while preserving core functions"}, {"id": "472d11b1-a176-44ca-a8b2-22935c0ab39f", "type": "concept", "title": "Monitoring evidence updates, sunset criteria, and living products"}], "description": "A successful launch is not the endpoint; practices must remain feasible, effective, equitable, and aligned with evolving evidence."}]}, {"id": "2c3a8329-98a6-42f8-9fb0-441ea642f0a8", "type": "topic", "title": "Capstone: Evidence-to-Practice Project Blueprint", "description": "The capstone integrates the entire course into a decision-ready proposal. It may be based on a real practice concern, but learners must not collect identifiable patient data or initiate a change without institutional authorization and appropriate oversight.", "children": [{"id": "9675c0b9-3046-4d7d-b465-666da548a90d", "type": "subtopic", "title": "Define", "children": [{"id": "98e826f4-99e1-4d2b-80fd-d725a048ac8e", "type": "concept", "title": "Practice problem and significance"}, {"id": "30715ec5-6b9a-4532-be6f-56e82d5a867f", "type": "concept", "title": "Stakeholder-validated question"}, {"id": "ced1a939-3210-4a9a-b412-50177056f56d", "type": "concept", "title": "Current-state data and equity implications"}]}, {"id": "f661edaa-adea-4a9a-944e-72cee1d813a3", "type": "subtopic", "title": "Discover", "children": [{"id": "fda2fe76-8e6d-45d7-ac14-1a65adefd96a", "type": "concept", "title": "Reproducible search"}, {"id": "a559f431-1aea-4ffa-afec-4da38c44195d", "type": "concept", "title": "Evidence table and critical appraisal"}, {"id": "c99134dc-4244-4888-8cb2-4ee09af7f25e", "type": "concept", "title": "Certainty, guideline, and applicability synthesis"}]}, {"id": "ab6e784e-d331-495b-bc8e-03ea33ae2491", "type": "subtopic", "title": "Design", "children": [{"id": "76a6d5ae-0e1b-4e59-85fb-ebcbb3831a53", "type": "concept", "title": "Recommendation and rationale"}, {"id": "a0aa248d-4b03-4846-ab96-9e9218085964", "type": "concept", "title": "Model, determinants, and implementation strategies"}, {"id": "43e5425b-f3d3-44e8-aac7-6606b38b4581", "type": "concept", "title": "Ethics, engagement, informatics, and resource plan"}]}, {"id": "6c03b912-0306-4d7c-8a0d-6668465ff310", "type": "subtopic", "title": "Evaluate", "children": [{"id": "a7d9f805-b9dc-4aa4-88c9-e0b52999a705", "type": "concept", "title": "Process, outcome, balancing, implementation, and equity measures"}, {"id": "e060f98d-6d71-4a86-a2fd-d5557121bfbb", "type": "concept", "title": "Data source, timing, analysis, and feedback plan"}, {"id": "6fb0e799-dab2-44b1-93fd-ce4be28350b2", "type": "concept", "title": "Sustainment, spread, de-implementation, and updating criteria"}]}, {"id": "6ab01f15-8c6b-4fb9-a582-762242fe4232", "type": "subtopic", "title": "Disseminate", "children": [{"id": "8592be3c-de7e-431e-bbfa-f32821719e74", "type": "concept", "title": "Patient-facing product"}, {"id": "77487cb5-5619-4838-89ce-872ff7cb04ee", "type": "concept", "title": "Clinical/leadership brief"}, {"id": "dd56d9a2-9c87-410c-b044-16c5c130d2ca", "type": "concept", "title": "Scholarly poster or presentation"}]}]}], "dbBacked": true}$nrebpjson$::jsonb,
  is_catalog = true,
